  const checkoutBtn = document.getElementById('checkoutLynkBtnLink');
  if (checkoutBtn) {
    checkoutBtn.href = targetUrl;
  }
  const footerLink = document.getElementById('footerLynkLink');
  if (footerLink) {
    footerLink.href = targetUrl;
  }
  document.querySelectorAll('.dynamic-lynk-url').forEach(el => {
    if (el.tagName === 'A') el.href = targetUrl;
  });
