const STORAGE_KEY = "creator_class_data_v8";
const THEME_KEY = 'IRT_NAIK_KELAS_THEME';

// Current App State
let courseData = {};
let currentEditingCategoryId = null;
let isMemberUnlocked = false;
try {
  const sessionExp = parseInt(localStorage.getItem('creator_class_session_timeout') || '0', 10);
  if (sessionExp > 0 && Date.now() > sessionExp) {
    localStorage.removeItem('creator_class_member_unlocked');
    localStorage.removeItem('creator_class_session_timeout');
    isMemberUnlocked = false;
  } else {
    isMemberUnlocked = localStorage.getItem('creator_class_member_unlocked') === 'true';
  }
} catch (e) {
  isMemberUnlocked = false;
}

// =========================================================================
// 1. THEME ENGINE (DARK MODE & LIGHT MODE)
// =========================================================================
function initTheme() {
  const savedTheme = localStorage.getItem(THEME_KEY);
  const prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
  
  if (savedTheme === 'dark' || (!savedTheme && prefersDark)) {
    document.documentElement.classList.add('dark');
  } else {
    document.documentElement.classList.remove('dark');
  }
  updateThemeIcon();
}

function toggleTheme() {
  const isDark = document.documentElement.classList.toggle('dark');
  localStorage.setItem(THEME_KEY, isDark ? 'dark' : 'light');
  
  // Re-apply theme variables cleanly for the new light/dark state
  if (typeof applyThemeConfig === 'function') {
    applyThemeConfig(courseData?.themeConfig);
  }
  
  updateThemeIcon();
  showToast(isDark ? "Mode Gelap (Dark Mode) aktif" : "Mode Terang (Clean Light) aktif");
}

function updateThemeIcon() {
  const isDark = document.documentElement.classList.contains('dark');
  const themeBtnIcons = document.querySelectorAll('.theme-toggle-icon');
  themeBtnIcons.forEach(icon => {
    if (isDark) {
      icon.className = 'fa-solid fa-sun text-amber-400 theme-toggle-icon';
    } else {
      icon.className = 'fa-solid fa-moon text-purple-600 theme-toggle-icon';
    }
  });
}

