// 1. Render Navbar
function renderNavbar() {
  if (!courseData.brand) courseData.brand = {};
  const brandName = courseData.brand.name || "CREATOR CLASS";
  const brandTag = courseData.brand.tagline || courseData.brand.byline || "by IRT NAIK LEVEL";
  const rawByline = courseData.brand.byline || "IRT NAIK LEVEL";
  const brandByline = rawByline.replace(/^by\s+/i, '');

  const brandNameEls = document.querySelectorAll('.dynamic-brand-name');
  brandNameEls.forEach(el => el.textContent = brandName);

  const brandTagEls = document.querySelectorAll('.dynamic-brand-tag');
  brandTagEls.forEach(el => el.textContent = brandTag);

  const brandBylineEls = document.querySelectorAll('.dynamic-brand-byline');
  brandBylineEls.forEach(el => el.textContent = brandByline);

  // Logo rendering in Navbar, Mobile Drawer & Footer
  const navLogoContainer = document.getElementById('navBrandLogoContainer');
  applyBrandLogoToElement(navLogoContainer, courseData.brand.logoUrl, brandName, false);

  const mobileDrawerLogo = document.getElementById('mobileDrawerLogoContainer');
  applyBrandLogoToElement(mobileDrawerLogo, courseData.brand.logoUrl, brandName, false);

  const footerLogoContainer = document.getElementById('footerBrandLogoContainer');
  applyBrandLogoToElement(footerLogoContainer, courseData.brand.logoUrl, brandName, true);

  const navContainer = document.getElementById('navLinksContainer');
  if (navContainer && courseData.brand.navLinks) {
    const activeNavLinks = courseData.brand.navLinks.filter(l => !l.label.toLowerCase().includes('bonus') && l.href !== '#tools' && l.label.toLowerCase() !== 'faq' && l.href !== '#faq' && !l.label.toLowerCase().includes('alur') && l.href !== '#proses' && !l.label.toLowerCase().includes('siapa') && l.href !== '#audiens');
    navContainer.innerHTML = activeNavLinks.map(link => `
      <a href="${link.href}" class="whitespace-nowrap px-2 lg:px-2.5 py-1.5 text-xs lg:text-[13px] font-semibold text-slate-700 dark:text-slate-200 hover:text-purple-600 dark:hover:text-purple-400 rounded-lg hover:bg-purple-50 dark:hover:bg-white/5 transition-all inline-flex items-center leading-none">
        ${link.label}
      </a>
    `).join('');
  }

  const mobileNavContainer = document.getElementById('mobileNavLinksContainer');
  if (mobileNavContainer && courseData.brand.navLinks) {
    const activeMobileNavLinks = courseData.brand.navLinks.filter(l => !l.label.toLowerCase().includes('bonus') && l.href !== '#tools' && l.label.toLowerCase() !== 'faq' && l.href !== '#faq' && !l.label.toLowerCase().includes('alur') && l.href !== '#proses' && !l.label.toLowerCase().includes('siapa') && l.href !== '#audiens');
    mobileNavContainer.innerHTML = activeMobileNavLinks.map(link => `
      <a href="${link.href}" onclick="toggleMobileMenu()" class="block py-2 text-sm font-medium text-slate-700 dark:text-slate-200 hover:text-purple-600 dark:hover:text-purple-400">
        ${link.label}
      </a>
    `).join('');
  }

  // Update Mobile Drawer CTA button price dynamically
  const mobileDrawerCta = document.getElementById('mobileDrawerCtaBtn');
  const promoVal = courseData.pricing?.promoPrice || courseData.pricing?.price || 'Rp 99.000';
  if (mobileDrawerCta) {
    mobileDrawerCta.textContent = courseData.hero?.ctaPrimary || `Gabung Sekarang — ${promoVal}`;
  }
}

// 2. Render Hero
