// 6. Render Mentor / Founder (Foto 2)
function renderMentor() {
  if (!courseData.mentor) {
    courseData.mentor = JSON.parse(JSON.stringify(window.DEFAULT_COURSE_DATA.mentor || {}));
  }
  const mentor = courseData.mentor;
  if (!mentor) return;

  const nameEl = document.getElementById('mentorName');
  if (nameEl) nameEl.textContent = mentor.name || 'Lia Naik Level';

  const roleEl = document.getElementById('mentorRole');
  if (roleEl) roleEl.textContent = mentor.role || 'Komunitas & Mentor Edukasi AI';

  const quoteEl = document.getElementById('mentorQuote');
  if (quoteEl) quoteEl.textContent = `"${mentor.quote || 'Kami percaya setiap Ibu memiliki potensi luar biasa. Teknologi AI bukan untuk menggantikan peran kita, melainkan menjadi sayap agar kita bisa berkarya dan mandiri secara finansial dari rumah.'}"`;

  const handleEl = document.getElementById('mentorHandle');
  if (handleEl) {
    const handleText = mentor.socialHandle || '@irtnaikkelas';
    handleEl.innerHTML = `<i class="fa-brands fa-instagram text-base"></i><span>${handleText}</span>`;
    handleEl.href = mentor.socialLink || `https://instagram.com/${handleText.replace('@', '')}`;
  }

  // Render Foto Founder / Avatar
  const avatarContainer = document.getElementById('mentorAvatarContainer');
  if (avatarContainer) {
    const defaultMentorPhoto = "assets/foto_mentor_lia.jpg";
    const finalAvatar = (mentor.avatarUrl && mentor.avatarUrl.trim().length > 0) ? mentor.avatarUrl : defaultMentorPhoto;
    avatarContainer.className = 'w-48 h-48 sm:w-60 sm:h-60 aspect-square rounded-3xl bg-slate-900 text-white flex items-center justify-center shrink-0 shadow-xl relative overflow-hidden border-2 border-purple-500/30 group';
    avatarContainer.innerHTML = `
      <img src="${finalAvatar}" alt="${mentor.name || 'Mentor IRT Naik Level'}" class="w-full h-full aspect-square object-cover object-center group-hover:scale-105 transition-transform duration-500" style="image-rendering: auto;" onerror="this.src='${defaultMentorPhoto}'">
      <div class="absolute bottom-3 bg-black/75 backdrop-blur-md px-3 py-1 rounded-full text-[11px] font-mono text-emerald-400 border border-emerald-400/30 flex items-center gap-1.5 shadow-sm">
        <span class="w-1.5 h-1.5 rounded-full bg-emerald-400"></span> ${mentor.badge || 'Verified Community'}
      </div>
    `;
  }

  const highlightsContainer = document.getElementById('mentorHighlights');
  if (highlightsContainer && mentor.highlights) {
    highlightsContainer.innerHTML = mentor.highlights.map(h => `
      <div class="p-3 sm:p-4 rounded-2xl bg-white dark:bg-[#1e1e24] border border-slate-200/80 dark:border-white/10 shadow-xs text-center">
        <div class="font-heading text-xl sm:text-2xl font-bold text-purple-600 dark:text-purple-400">${h.value}</div>
        <div class="text-[11px] sm:text-xs text-slate-500 dark:text-slate-400 font-medium mt-1">${h.label}</div>
      </div>
    `).join('');
  }
}

