function openCategoryPreview(categoryId) {
  const cat = courseData.categories.find(c => c.id === categoryId);
  if (!cat) return;

  currentEditingCategoryId = categoryId;

  const imgEl = document.getElementById('modalCatImg');
  const titleEl = document.getElementById('modalCatTitle');
  const descEl = document.getElementById('modalCatDesc');

  if (imgEl) imgEl.src = cat.imageUrl || 'https://www.animato.id/cinema/general.webp';
  if (titleEl) titleEl.textContent = cat.title;
  if (descEl) descEl.textContent = cat.desc;

  // Fill in the edit fields inside the modal
  const editTitle = document.getElementById('quickEditTitle');
  const editDesc = document.getElementById('quickEditDesc');
  const editImg = document.getElementById('quickEditImgUrl');

  if (editTitle) editTitle.value = cat.title;
  if (editDesc) editDesc.value = cat.desc;
  if (editImg) editImg.value = cat.imageUrl;

  openModal('previewModal');
}

function handleQuickCardSave(e) {
  e.preventDefault();
  if (!currentEditingCategoryId) return;

  const catIndex = courseData.categories.findIndex(c => c.id === currentEditingCategoryId);
  if (catIndex === -1) return;

  const newTitle = document.getElementById('quickEditTitle').value.trim();
  const newDesc = document.getElementById('quickEditDesc').value.trim();
  const newImgUrl = document.getElementById('quickEditImgUrl').value.trim();

  if (newTitle) courseData.categories[catIndex].title = newTitle;
  if (newDesc) courseData.categories[catIndex].desc = newDesc;
  if (newImgUrl) courseData.categories[catIndex].imageUrl = newImgUrl;

  saveData(courseData);
  closeModal('previewModal');
  showToast("Foto dan deskripsi kartu berhasil diperbarui!");
}

