function handleEditorSubmit(e) {
  e.preventDefault();

  const brandName = document.getElementById('editBrandName')?.value?.trim() || courseData.brand?.name || 'CREATOR CLASS';
  const brandLogo = document.getElementById('editBrandLogoUrl')?.value?.trim();
  const brandTagline = document.getElementById('editBrandTagline')?.value?.trim() || courseData.brand?.tagline || 'by IRT NAIK LEVEL';
  const heroTitle = document.getElementById('editHeroTitle')?.value?.trim() || courseData.hero?.title || 'Belajar Animasi AI Untuk Pemula';
  const heroHighlight = document.getElementById('editHeroHighlight')?.value?.trim() || courseData.hero?.highlightText || 'Bisa dari Rumah Sambil Urus Keluarga';
  const classTitle = document.getElementById('editClassTitle')?.value?.trim() || courseData.pricing?.classTitle || 'Kelas Animasi AI untuk Pemula';
  const normalPrice = document.getElementById('editNormalPrice')?.value?.trim() || courseData.pricing?.normalPrice || 'Rp 20.000';
  const promoPrice = document.getElementById('editPromoPrice')?.value?.trim() || courseData.pricing?.promoPrice || 'Rp 99.000';
  const mentorName = document.getElementById('editMentorName')?.value?.trim() || courseData.mentor?.name || 'Sutradara Video Animasi AI';

  const updated = JSON.parse(JSON.stringify(courseData));
  if (!updated.brand) updated.brand = {};
  if (!updated.hero) updated.hero = {};
  if (!updated.pricing) updated.pricing = {};
  if (!updated.mentor) updated.mentor = {};
  if (!updated.categories) updated.categories = [];
  if (!updated.steps) updated.steps = [];

  updated.brand.name = brandName;
  if (brandLogo !== undefined) {
    updated.brand.logoUrl = brandLogo;
  }
  updated.brand.tagline = brandTagline;
  updated.brand.byline = brandTagline;
  updated.hero.title = heroTitle;
  updated.hero.highlightText = heroHighlight;
  updated.pricing.classTitle = classTitle;
  updated.pricing.normalPrice = normalPrice;
  updated.pricing.originalPrice = normalPrice;
  updated.pricing.promoPrice = promoPrice;
  updated.pricing.price = promoPrice;
  updated.hero.ctaPrimary = `Gabung Sekarang — ${promoPrice}`;
  updated.mentor.name = mentorName;

  // Update categories from list
  updated.categories.forEach((c, i) => {
    const tEl = document.getElementById(`editCatTitle_${i}`);
    const dEl = document.getElementById(`editCatDesc_${i}`);
    const imgEl = document.getElementById(`editCatImg_${i}`);
    if (tEl) c.title = tEl.value;
    if (dEl) c.desc = dEl.value;
    if (imgEl && imgEl.value) c.imageUrl = imgEl.value;
  });

  // Update steps
  updated.steps.forEach((st, i) => {
    const tEl = document.getElementById(`editStepTitle_${i}`);
    const dEl = document.getElementById(`editStepDesc_${i}`);
    const tlEl = document.getElementById(`editStepTools_${i}`);
    if (tEl) st.title = tEl.value;
    if (dEl) st.desc = dEl.value;
    if (tlEl) st.tools = tlEl.value;
  });

  // 1. Immediately close modal with zero delay
  closeModal('editorModal');
  const modalEl = document.getElementById('editorModal');
  if (modalEl) {
    modalEl.classList.remove('active');
    modalEl.style.display = 'none';
  }
  document.body.style.overflow = 'auto';

  // 2. Set update timestamp & persist
  updated.lastUpdated = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) + ' WIB';
  courseData = updated;
  // Live re-render elements on page so user sees instant results
  renderHero();
  renderPricing();
  renderCategories(null);
  renderAudiences();
  renderSteps();
  renderFaqs();
  renderNavbar();

  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(courseData));
  } catch (err) {}

  // 3. Immediately render all components
  renderAll();
  showToast("✅ Seketika tersimpan! Semua perubahan landing page telah terupdate.");
}

