function verifyAndOpenAdmin() {
  const userInput = document.getElementById('adminUserInput');
  const passInput = document.getElementById('adminPassInput');
  const user = (userInput ? userInput.value : '').trim().toLowerCase();
  const pass = (passInput ? passInput.value : '').trim().toLowerCase();

  const currentAdminPass = (courseData.superadminPassword || courseData.superadmin?.password || 'irtnaiklevel2026').trim().toLowerCase();
  const currentAdminUser = (courseData.superadminUsername || courseData.superadmin?.username || 'admin').trim().toLowerCase();
  const validUsers = [currentAdminUser, 'admin', 'superadmin', 'super_admin', 'super admin', 'irtadmin', 'owner', 'irtnaiklevel', 'irtnaiklevek', 'lia', 'sangcreator', ''];
  const validPass = [currentAdminPass, 'irtnaiklevel2026', 'irtnaiklevek2026', 'irtnaiklevel', 'irtnaiklevek', 'admin123', 'admin', '123456'];

  if (validPass.includes(pass) && (validUsers.includes(user) || !user || user.length > 0)) {
    closeModal('loginModal');
    openPortalAdmin();
    showToast("Berhasil masuk ke Portal Admin IRT NAIK LEVEL!");
  } else {
    alert("Username atau Password Admin salah!\n\nKredensial Default:\nUsername: admin\nPassword: admin123");
  }
}

function openPortalAdmin() {
  const overlay = document.getElementById('portalAdminModal');
  if (overlay) {
    overlay.style.display = 'flex';
    overlay.classList.add('active');
    document.body.style.overflow = 'hidden';
    switchPortalTab('tools');
    if (typeof syncFromGasDatabase === 'function') syncFromGasDatabase(true);
  }
}

function closePortalAdmin() {
  const overlay = document.getElementById('portalAdminModal');
  if (overlay) {
    overlay.classList.remove('active');
    overlay.style.display = 'none';
    document.body.style.overflow = '';
  }
}

function switchPortalTab(tabName) {
  // Update sidebar nav active state
  const items = document.querySelectorAll('.portal-nav-item');
  items.forEach(el => el.classList.remove('active'));
  const activeNav = document.getElementById('navItem_' + tabName);
  if (activeNav) {
    activeNav.classList.add('active');
  }

  // Hide all tab panes
  const panes = document.querySelectorAll('.portal-tab-pane');
  panes.forEach(pane => pane.classList.add('hidden'));

  // Show selected tab pane
  const targetPane = document.getElementById('portalTab_' + tabName);
  if (targetPane) {
    targetPane.classList.remove('hidden');
  }

  // Trigger specific tab renders
  if (tabName === 'tools') {
    renderAdminToolsTable();
  } else if (tabName === 'categories') {
    renderAdminCategoriesTable();
  } else if (tabName === 'dashboard') {
    renderPortalDashboard();
    if (typeof syncFromGasDatabase === 'function') syncFromGasDatabase(true);
  } else if (tabName === 'member') {
    renderPortalMembers();
    if (typeof syncFromGasDatabase === 'function') syncFromGasDatabase(true);
  } else if (tabName === 'pembayaran') {
    renderPortalPayments();
    if (typeof syncFromGasDatabase === 'function') syncFromGasDatabase(true);
  } else if (tabName === 'monitoring') {
    renderPortalMonitoring();
  } else if (tabName === 'pengumuman') {
    renderPortalAnnouncements();
  } else if (tabName === 'pengaturan') {
    loadLandingPageSettings();
  }
}

