function renderPortalDashboard() {
  const tools = courseData.portalTools || [];
  const members = courseData.portalMembers || (window.DEFAULT_COURSE_DATA.portalMembers || []);
  const totalViews = tools.reduce((acc, t) => acc + (t.views || 0), 0);

  const dashTools = document.getElementById('dashTotalTools');
  const dashMembers = document.getElementById('dashTotalMembers');
  const dashViews = document.getElementById('dashTotalViews');
  const topList = document.getElementById('dashTopToolsList');

  if (dashTools) dashTools.textContent = tools.length;
  if (dashMembers) dashMembers.textContent = members.length + 2835; // Total simulated
  if (dashViews) dashViews.textContent = totalViews;

  if (topList) {
    const sorted = [...tools].sort((a, b) => (b.views || 0) - (a.views || 0)).slice(0, 4);
    topList.innerHTML = sorted.map((t, idx) => `
      <div class="flex items-center justify-between p-3 rounded-xl bg-[#181a24] border border-white/5">
        <div class="flex items-center gap-3">
          <span class="w-6 h-6 rounded-full bg-purple-900/60 text-purple-300 font-bold text-xs flex items-center justify-center font-mono">
            ${idx + 1}
          </span>
          <img src="${t.coverUrl || 'https://www.animato.id/cinema/asmr.webp'}" class="w-8 h-8 rounded-lg object-cover" alt="">
          <div>
            <h4 class="font-bold text-white text-xs">${t.name}</h4>
            <span class="text-[10px] text-slate-400 font-mono">${t.category}</span>
          </div>
        </div>
        <div class="text-right">
          <span class="text-xs font-mono font-bold text-purple-300">${t.views || 0} views</span>
          <span class="block text-[10px] text-emerald-400">Aktif</span>
        </div>
      </div>
    `).join('');
  }
}

