let memberSearchQuery = '';

function renderPortalMembers() {
  const tbody = document.getElementById('portalMembersTableBody');
  const countEl = document.getElementById('totalMembersCount');
  if (!tbody) return;

  const members = courseData.portalMembers || (window.DEFAULT_COURSE_DATA.portalMembers || []);
  if (countEl) countEl.textContent = members.length;

  const filtered = members.filter(m => {
    if (!memberSearchQuery) return true;
    const q = memberSearchQuery.toLowerCase();
    return m.name.toLowerCase().includes(q) || m.email.toLowerCase().includes(q) || m.wa.includes(q);
  });

  const todayStr = new Date().toISOString().slice(0, 10);
  tbody.innerHTML = filtered.map(m => {
    const todayDevs = (m.devices || []).filter(d => d.date === todayStr);
    const devCount = todayDevs.length;
    const isOverLimit = devCount > 3 || (courseData.securityAlerts || []).some(a => a.memberEmail === m.email);

    return `
    <tr class="hover:bg-white/[0.02] transition-colors">
      <td class="py-3 px-4 font-bold text-white flex items-center gap-2.5">
        <div class="w-7 h-7 rounded-full bg-purple-600/30 text-purple-300 font-bold flex items-center justify-center text-xs">
          ${m.name.charAt(0)}
        </div>
        <div>
          <div>${m.name}</div>
          <div class="text-[10px] text-slate-500 font-mono flex items-center gap-1 mt-0.5">
            <span class="px-1.5 py-0.5 rounded ${isOverLimit ? 'bg-rose-500/20 text-rose-300 font-bold border border-rose-500/30' : (devCount >= 2 ? 'bg-amber-500/20 text-amber-300' : 'bg-emerald-500/20 text-emerald-300')} text-[10px]">
              📱 ${devCount}/2 Perangkat
            </span>
          </div>
        </div>
      </td>
      <td class="py-3 px-4 text-xs font-mono text-slate-400">${m.email || '-'}</td>
      <td class="py-3 px-4 text-xs font-mono text-slate-400">${m.wa || '-'}</td>
      <td class="py-3 px-4 text-xs font-mono font-bold text-amber-400">${m.activationCode || '-'}</td>
      <td class="py-3 px-4">
        <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${m.status === 'Aktif' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-rose-500/20 text-rose-400'}">
          ${m.status || 'Aktif'}
        </span>
      </td>
      <td class="py-3 px-4">
        <div class="flex items-center gap-1.5">
          <button onclick="handleAdminResetDevice('${m.email}')" class="px-2 py-1 rounded-lg bg-amber-500/10 hover:bg-amber-500/20 text-amber-300 border border-amber-500/30 text-[10px] font-semibold transition-all flex items-center gap-1" title="Reset Perangkat Member">
            <i class="fa-solid fa-rotate-left"></i> Reset Device
          </button>
          <button onclick="toggleMemberAccess('${m.id}')" class="px-2 py-1 rounded-lg ${m.status === 'Aktif' ? 'bg-rose-500/10 hover:bg-rose-500/20 text-rose-300 border border-rose-500/30' : 'bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-300 border border-emerald-500/30'} text-[10px] font-semibold transition-all">
            ${m.status === 'Aktif' ? 'Nonaktifkan' : 'Aktifkan'}
          </button>
          <button onclick="deleteMemberFromPortal('${m.id}')" class="p-1 rounded-lg bg-white/5 hover:bg-rose-500/20 text-slate-400 hover:text-rose-400 text-xs transition-colors" title="Hapus Member">
            <i class="fa-solid fa-trash-can"></i>
          </button>
        </div>
      </td>
    </tr>`;
  }).join('');
}

function toggleMemberAccess(memberId) {
  const members = courseData.portalMembers || [];
  const mem = members.find(m => m.id === memberId);
  if (!mem) return;

  const willDeactivate = (mem.status === 'Aktif' || !mem.status);
  const newStatus = willDeactivate ? 'Nonaktif' : 'Aktif';
  mem.status = newStatus;

  // Also sync with portalPayments
  if (courseData.portalPayments) {
    courseData.portalPayments.forEach(p => {
      const match = (p.activationCode && mem.activationCode && p.activationCode.toUpperCase() === mem.activationCode.toUpperCase()) ||
                    (p.email && mem.email && p.email.toLowerCase() === mem.email.toLowerCase()) ||
                    (p.name && mem.name && p.name.toLowerCase() === mem.name.toLowerCase());
      if (match) {
        p.status = willDeactivate ? 'Nonaktif' : 'Lunas & Teraktivasi';
      }
    });
  }

  // Fast direct save to LocalStorage (Instant - No renderAll lag!)
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(courseData));
  } catch (e) {
    console.warn("Storage save error:", e);
  }

  renderPortalMembers();
  if (typeof renderPortalPayments === 'function') renderPortalPayments();
  if (typeof renderPortalDashboard === 'function') renderPortalDashboard();

  // Instant Revocation if this device/browser belongs to that member
  const curCode = localStorage.getItem('creator_class_active_code');
  const curEmail = localStorage.getItem('creator_class_member_email');
  const curName = localStorage.getItem('creator_class_member_name');

  const matchesCurrent = 
    (curCode && mem.activationCode && curCode.toUpperCase() === mem.activationCode.toUpperCase()) ||
    (curEmail && mem.email && curEmail.toLowerCase() === mem.email.toLowerCase()) ||
    (curName && mem.name && curName.toLowerCase() === mem.name.toLowerCase());

  if (matchesCurrent && willDeactivate) {
    isMemberUnlocked = false;
    localStorage.removeItem('creator_class_member_unlocked');
    updateMemberAccessUI();
  }

  showToast(willDeactivate ? `Akses ${mem.name} DINONAKTIFKAN!` : `Akses ${mem.name} DIAKTIFKAN!`);
}

function deleteMemberFromPortal(memberId) {
  const members = courseData.portalMembers || [];
  const mem = members.find(m => m.id === memberId);
  if (!mem) return;

  if (confirm(`Yakin ingin MENGHAPUS member "${mem.name}" (${mem.email})?\n\nKode aktivasi (${mem.activationCode || 'IRT-ACT-XXXX'}) akan dicabut dan member tersebut tidak akan bisa lagi mengakses website kelas.`)) {
    // Track in deletedCodes list so demo/fallback can never authenticate them
    if (!courseData.deletedCodes) courseData.deletedCodes = [];
    if (mem.activationCode) courseData.deletedCodes.push(mem.activationCode.toUpperCase());
    if (mem.email) courseData.deletedCodes.push(mem.email.toLowerCase());
    if (mem.name) courseData.deletedCodes.push(mem.name.toLowerCase());

    // Remove from portalMembers
    courseData.portalMembers = (courseData.portalMembers || []).filter(m => m.id !== memberId);

    // Also remove from portalPayments
    if (courseData.portalPayments) {
      courseData.portalPayments = courseData.portalPayments.filter(p => {
        const matches = (p.activationCode && mem.activationCode && p.activationCode.toUpperCase() === mem.activationCode.toUpperCase()) ||
                        (p.email && mem.email && p.email.toLowerCase() === mem.email.toLowerCase()) ||
                        (p.name && mem.name && p.name.toLowerCase() === mem.name.toLowerCase());
        return !matches;
      });
    }

    // Fast direct save to LocalStorage (Instant - No renderAll lag!)
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(courseData));
    } catch (e) {
      console.warn("Storage save error:", e);
    }

    renderPortalMembers();
    if (typeof renderPortalPayments === 'function') renderPortalPayments();
    if (typeof renderPortalDashboard === 'function') renderPortalDashboard();

    // Instant Revocation if current session matches
    const curCode = localStorage.getItem('creator_class_active_code');
    const curEmail = localStorage.getItem('creator_class_member_email');
    const curName = localStorage.getItem('creator_class_member_name');
    const matchesCurrent = 
      (curCode && mem.activationCode && curCode.toUpperCase() === mem.activationCode.toUpperCase()) ||
      (curEmail && mem.email && curEmail.toLowerCase() === mem.email.toLowerCase()) ||
      (curName && mem.name && curName.toLowerCase() === mem.name.toLowerCase());

    if (matchesCurrent) {
      isMemberUnlocked = false;
      localStorage.removeItem('creator_class_member_unlocked');
      localStorage.removeItem('creator_class_active_code');
      updateMemberAccessUI();
    }

    showToast(`Member "${mem.name}" berhasil dihapus.`);
  }
}

function filterPortalMembers(q) {
  memberSearchQuery = q;
  renderPortalMembers();
}

function openAddMemberPrompt() {
  const name = prompt("Nama Lengkap Member Baru:");
  if (!name) return;
  const wa = prompt("Nomor WhatsApp (Contoh: 08123456789):");
  if (!wa) return;
  const email = prompt("Email Aktif:");

  if (!courseData.portalMembers) {
    courseData.portalMembers = JSON.parse(JSON.stringify(window.DEFAULT_COURSE_DATA.portalMembers || []));
  }

  const newMem = {
    id: 'mem-' + Date.now(),
    name,
    email: email || 'member@irtnaikkelas.com',
    wa,
    status: 'Aktif',
    date: 'Hari ini',
    package: 'Kelas Animasi AI'
  };

  courseData.portalMembers.unshift(newMem);
  saveData(courseData);
  renderPortalMembers();
  showToast(`Member baru "${name}" berhasil ditambahkan!`);
}

