function renderPortalAnnouncements() {
  const listEl = document.getElementById('announcementsList');
  if (!listEl) return;

  const announcements = courseData.portalAnnouncements || (window.DEFAULT_COURSE_DATA.portalAnnouncements || []);

  listEl.innerHTML = announcements.map((ann, idx) => `
    <div class="p-4 rounded-xl bg-[#181a24] border border-white/10 space-y-2">
      <div class="flex items-center justify-between">
        <h4 class="font-bold text-white text-xs flex items-center gap-2">
          <span>${ann.title}</span>
          <span class="px-2 py-0.5 rounded-full text-[9px] font-mono bg-purple-500/20 text-purple-300 font-bold">${ann.status}</span>
        </h4>
        <div class="flex items-center gap-2">
          <span class="text-[10px] text-slate-500 font-mono">${ann.date}</span>
          <button onclick="deleteAnnouncement(${idx})" class="text-rose-400 hover:text-rose-300 text-xs" title="Hapus Pengumuman">
            <i class="fa-regular fa-trash-can"></i>
          </button>
        </div>
      </div>
      <p class="text-xs text-slate-300 leading-relaxed">${ann.content}</p>
    </div>
  `).join('');
}

function handleAnnouncementSubmit(e) {
  e.preventDefault();
  const title = document.getElementById('annTitleInput').value.trim();
  const content = document.getElementById('annContentInput').value.trim();

  if (!courseData.portalAnnouncements) {
    courseData.portalAnnouncements = JSON.parse(JSON.stringify(window.DEFAULT_COURSE_DATA.portalAnnouncements || []));
  }

  courseData.portalAnnouncements.unshift({
    id: 'ann-' + Date.now(),
    title,
    content,
    date: 'Hari ini',
    status: 'Aktif'
  });

  saveData(courseData);
  document.getElementById('annTitleInput').value = '';
  document.getElementById('annContentInput').value = '';
  renderPortalAnnouncements();
  showToast("Pengumuman berhasil diterbitkan!");
}

function deleteAnnouncement(idx) {
  if (confirm("Hapus pengumuman ini?")) {
    courseData.portalAnnouncements.splice(idx, 1);
    saveData(courseData);
    renderPortalAnnouncements();
    showToast("Pengumuman dihapus.");
  }
}


function toggleMemberToolsVisibility(isChecked) {
  const label = document.getElementById('memberToolsStatusLabel');
  if (label) {
    label.textContent = isChecked ? 'ON (Tampil)' : 'OFF (Sembunyi)';
    label.className = isChecked ? 'text-emerald-400 font-semibold text-[11px]' : 'text-slate-500 font-semibold text-[11px]';
  }
  const memberSection = document.getElementById('materi');
  if (memberSection) {
    memberSection.style.display = isChecked ? '' : 'none';
  }
  showToast(isChecked ? "Menu tools untuk member ditampilkan" : "Menu tools untuk member disembunyikan");
}

function filterAdminTools(val) {
  adminToolSearchQuery = val;
  renderAdminToolsTable();
}

function filterAdminCategory(val) {
  adminToolCategoryFilter = val || 'all';
  renderAdminToolsTable();
}

function updateToolCategoryDirectly(toolId, newCategory) {
  const tool = (courseData.portalTools || []).find(t => t.id === toolId);
  if (tool) {
    tool.category = newCategory;
    courseData.lastUpdated = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) + ' WIB';
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(courseData));
    } catch (e) {}
    renderAdminToolsTable();
    if (typeof renderMemberTools === 'function') {
      renderMemberTools();
    }
    showToast(`Kategori "${tool.name}" diubah ke "${newCategory}"`);
  }
}

function renderAdminToolsTable() {
  const tbody = document.getElementById('adminToolsTableBody');
  const countEl = document.getElementById('totalToolsCount');
  if (!tbody) return;

  const tools = courseData.portalTools || [];
  if (countEl) countEl.textContent = tools.length;

  const filtered = tools.filter(t => {
    // 1. Category Filter from Dropdown
    if (adminToolCategoryFilter && adminToolCategoryFilter !== 'all') {
      if (t.category !== adminToolCategoryFilter) return false;
    }

    // 2. Search query filter (supports level number e.g. "20", "level 20")
    if (!adminToolSearchQuery) return true;
    const q = adminToolSearchQuery.toLowerCase().trim();
    const lvlMatch = q.match(/^(\d+)$/) || q.match(/^level\s*(\d+)$/i) || q.match(/^lvl\s*(\d+)$/i);
    if (lvlMatch) {
      const targetLvl = parseInt(lvlMatch[1], 10);
      if (t.levelNum === targetLvl || t.id === `lvl-${targetLvl}`) return true;
    }
    return (t.name || '').toLowerCase().includes(q) || (t.category || '').toLowerCase().includes(q) || (t.desc || '').toLowerCase().includes(q);
  });

  if (filtered.length === 0) {
    tbody.innerHTML = `
      <tr>
        <td colspan="6" class="py-8 text-center text-slate-400">
          Tidak ditemukan tools untuk pencarian / kategori ini.
        </td>
      </tr>
    `;
    return;
  }

  tbody.innerHTML = filtered.map(t => {
    const isOnline = t.status !== false;
    const cover = t.coverUrl || 'https://www.animato.id/cinema/asmr.webp';
    const views = t.views || 0;
    const currentCategory = t.category || getOfficialCategory(t.levelNum, t.name);

    return `
      <tr class="hover:bg-white/[0.02] transition-colors border-b border-white/5">
        <!-- Drag Handle Icon -->
        <td class="py-3 px-4 text-center text-slate-500 font-mono text-sm cursor-grab select-none">
          ⋮⋮
        </td>

        <!-- Nama & Cover Foto -->
        <td class="py-3 px-4">
          <div class="flex items-center gap-3">
            <div class="w-10 h-10 rounded-lg overflow-hidden bg-slate-800 border border-white/10 shrink-0">
              <img src="${cover}" alt="${t.name}" class="w-full h-full object-cover">
            </div>
            <div>
              <div class="font-bold text-white text-xs">${t.name}</div>
              <div class="text-[11px] text-slate-400 line-clamp-1 max-w-xs mt-0.5">${t.desc || '-'}</div>
              <div class="flex items-center gap-2 mt-1">
                ${t.toolUrl ? `<a href="${t.toolUrl}" target="_blank" class="text-[10px] text-purple-400 hover:underline"><i class="fa-solid fa-link"></i> Link Tool</a>` : ''}
                ${((t.videos && t.videos.length > 0) || t.videoUrl) ? `
                  <a onclick="openVideoModal('${t.id}')" class="text-[10px] text-rose-400 hover:underline inline-flex items-center gap-1 cursor-pointer">
                    <i class="fa-brands fa-youtube text-red-500"></i> ${(t.videos && t.videos.length > 1) ? `${t.videos.length} Video Tutor` : 'Video Tutor'}
                  </a>
                ` : ''}
                ${t.markdownPrompt ? `
                  <a onclick="openPromptViewer('${t.id}')" class="text-[10px] text-emerald-400 hover:underline inline-flex items-center gap-1 cursor-pointer">
                    <i class="fa-brands fa-markdown text-emerald-400"></i> Prompt MD
                  </a>
                ` : ''}
              </div>
            </div>
          </div>
        </td>

        <!-- Kategori (Pilihan ke Bawah / Dropdown Langsung di Baris Tabel) -->
        <td class="py-3 px-4">
          <div class="relative inline-block w-full min-w-[210px] max-w-[260px]">
            <select onchange="updateToolCategoryDirectly('${t.id}', this.value)" class="w-full text-[11px] font-semibold px-3 py-1.5 rounded-xl bg-[#1e202c] hover:bg-[#252837] text-purple-300 border border-white/10 focus:outline-none focus:border-purple-500 cursor-pointer appearance-none pr-7 transition-colors shadow-sm">
              ${OFFICIAL_CATEGORIES.map(c => `
                <option value="${c}" ${currentCategory === c ? 'selected' : ''} class="bg-[#14151c] text-white py-1">
                  ${c}
                </option>
              `).join('')}
            </select>
            <i class="fa-solid fa-chevron-down absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-400 text-[9px] pointer-events-none"></i>
          </div>
        </td>

        <!-- Status Switch (ON/OFF) -->
        <td class="py-3 px-4 text-center">
          <label class="switch-toggle scale-75 inline-block">
            <input type="checkbox" ${isOnline ? 'checked' : ''} onchange="toggleToolStatus('${t.id}')">
            <span class="switch-slider"></span>
          </label>
        </td>

        <!-- Dilihat (Views) -->
        <td class="py-3 px-4 text-center font-mono font-semibold text-slate-300">
          ${views}
        </td>

        <!-- Aksi (Edit & Hapus) -->
        <td class="py-3 px-4 text-center">
          <div class="inline-flex items-center gap-2">
            <button onclick="openEditToolModal('${t.id}')" class="w-7 h-7 rounded-lg bg-white/5 hover:bg-purple-600 text-slate-300 hover:text-white flex items-center justify-center transition-colors" title="Edit Tools">
              <i class="fa-solid fa-pen text-[11px]"></i>
            </button>
            <button onclick="deleteTool('${t.id}')" class="w-7 h-7 rounded-lg bg-white/5 hover:bg-rose-600 text-rose-400 hover:text-white flex items-center justify-center transition-colors" title="Hapus Tools">
              <i class="fa-regular fa-trash-can text-[11px]"></i>
            </button>
          </div>
        </td>
      </tr>
    `;
  }).join('');
}

function toggleToolStatus(toolId) {
  const tool = (courseData.portalTools || []).find(t => t.id === toolId);
  if (tool) {
    tool.status = tool.status === false ? true : false;
    courseData.lastUpdated = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) + ' WIB';
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(courseData));
    } catch (e) {}
    renderAdminToolsTable();
    if (typeof renderMemberTools === 'function') {
      renderMemberTools();
    }
    showToast(`Status "${tool.name}" diubah ke ${tool.status ? 'Aktif' : 'Nonaktif'}`);
  }
}

function deleteTool(toolId) {
  const tool = (courseData.portalTools || []).find(t => t.id === toolId);
  if (!tool) return;

  if (confirm(`Yakin ingin menghapus tools "${tool.name}"?`)) {
    // 1. Remove from portalTools array immediately
    courseData.portalTools = (courseData.portalTools || []).filter(t => t.id !== toolId);
    courseData.lastUpdated = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) + ' WIB';

    // 2. Persist to storage immediately
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(courseData));
    } catch (e) {
      console.warn("Storage save error:", e);
    }

    // 3. Re-render admin tools table and member tools grid IMMEDIATELY (0ms)
    renderAdminToolsTable();
    if (typeof renderMemberTools === 'function') {
      renderMemberTools();
    }

    // 4. Update count badge in admin UI if present
    const countEl = document.getElementById('totalToolsCount');
    if (countEl) countEl.textContent = (courseData.portalTools || []).length;

    showToast(`Tools "${tool.name}" berhasil dihapus seketika.`);
  }
}

