function addToolLinkInputRow(title = '', url = '') {
  const container = document.getElementById('toolLinksContainer');
  if (!container) return;

  const count = container.querySelectorAll('.tool-link-row').length + 1;
  const defaultTitle = title || `Tools ${count}`;

  const rowId = 'toolLinkRow_' + Date.now() + '_' + Math.floor(Math.random() * 1000);
  const row = document.createElement('div');
  row.id = rowId;
  row.className = 'tool-link-row flex items-center gap-2 p-2 rounded-xl bg-[#161822] border border-white/10';

  row.innerHTML = `
    <div class="flex-1 grid grid-cols-1 sm:grid-cols-2 gap-2">
      <input type="text" value="${defaultTitle}" placeholder="Nama Tools (Misal: ChatGPT Studio / Viggle AI)" class="tool-link-title px-3 py-1.5 rounded-lg bg-[#0e0f14] border border-white/10 text-white text-xs focus:outline-none focus:border-purple-500 font-medium">
      <input type="url" value="${url || ''}" placeholder="Link Tools (https://...)" class="tool-link-url px-3 py-1.5 rounded-lg bg-[#0e0f14] border border-white/10 text-purple-300 font-mono text-[11px] focus:outline-none focus:border-purple-500">
    </div>
    <button type="button" onclick="removeToolLinkInputRow('${rowId}')" class="w-8 h-8 rounded-lg bg-rose-500/15 hover:bg-rose-500 text-rose-300 hover:text-white text-xs transition-colors shrink-0 flex items-center justify-center cursor-pointer" title="Hapus Tools Ini">
      <i class="fa-solid fa-trash text-[11px]"></i>
    </button>
  `;

  container.appendChild(row);
}

function removeToolLinkInputRow(rowId) {
  const row = document.getElementById(rowId);
  if (row) row.remove();
}

function updateCategoryDatalist() {
  const datalist = document.getElementById('categoryDatalist');
  if (!datalist) return;
  const catNames = (courseData.curriculumCategories || []).map(c => c.name).filter(Boolean);
  const toolCats = (courseData.portalTools || []).map(t => t.category).filter(Boolean);
  const cats = [...new Set([
    ...catNames,
    ...toolCats,
    ...OFFICIAL_CATEGORIES
  ])].filter(c => c !== 'Belum Dikelompokkan');
  datalist.innerHTML = cats.map(c => `<option value="${c}"></option>`).join('');
}

// DYNAMIC MULTI-VIDEO ROW GENERATOR FOR TOOL EDITOR
// ----------------------------------------------------
function addToolVideoInputRow(title = '', url = '') {
  const container = document.getElementById('toolVideosContainer');
  if (!container) return;

  const count = container.querySelectorAll('.tool-video-row').length + 1;
  const defaultTitle = title || `Video Part ${count}`;

  const rowId = 'vidRow_' + Date.now() + '_' + Math.floor(Math.random() * 1000);
  const row = document.createElement('div');
  row.id = rowId;
  row.className = 'tool-video-row flex items-center gap-2 p-2 rounded-xl bg-[#161822] border border-white/10';

  row.innerHTML = `
    <div class="flex-1 grid grid-cols-1 sm:grid-cols-2 gap-2">
      <input type="text" value="${defaultTitle}" placeholder="Judul Video (Misal: Part 1 - Pengenalan)" class="tool-video-title px-3 py-1.5 rounded-lg bg-[#0e0f14] border border-white/10 text-white text-xs focus:outline-none focus:border-purple-500 font-medium">
      <input type="url" value="${url || ''}" placeholder="Link YouTube (https://youtu.be/...)" class="tool-video-url px-3 py-1.5 rounded-lg bg-[#0e0f14] border border-white/10 text-purple-300 font-mono text-[11px] focus:outline-none focus:border-purple-500">
    </div>
    <button type="button" onclick="removeToolVideoInputRow('${rowId}')" class="w-8 h-8 rounded-lg bg-rose-500/15 hover:bg-rose-500 text-rose-300 hover:text-white text-xs transition-colors shrink-0 flex items-center justify-center" title="Hapus Video Ini">
      <i class="fa-solid fa-trash text-[11px]"></i>
    </button>
  `;

  container.appendChild(row);
}

function removeToolVideoInputRow(rowId) {
  const container = document.getElementById('toolVideosContainer');
  const row = document.getElementById(rowId);
  if (row) {
    row.remove();
  }
  // If all rows removed, ensure at least 1 empty row remains
  if (container && container.querySelectorAll('.tool-video-row').length === 0) {
    addToolVideoInputRow('Video 1: Tutorial Utama', '');
  }
}

// ----------------------------------------------------
// Tool Editor Modal (Create / Edit)
// ----------------------------------------------------
function openAddToolModal() {
  document.getElementById('toolFormId').value = '';
  document.getElementById('toolEditorModalTitle').textContent = 'Tambah Tools Materi Baru';
  document.getElementById('toolFormName').value = '';
  document.getElementById('toolFormCategory').value = OFFICIAL_CATEGORIES[0];
  document.getElementById('toolFormStatus').value = 'true';
  document.getElementById('toolFormCoverUrl').value = 'https://www.animato.id/cinema/asmr.webp';
  previewToolCover('https://www.animato.id/cinema/asmr.webp');
  document.getElementById('toolFormToolUrl').value = '';
  document.getElementById('toolFormDesc').value = '';
  if (document.getElementById('toolFormMarkdownPrompt')) document.getElementById('toolFormMarkdownPrompt').value = '';

  if (typeof updateCategoryDatalist === 'function') updateCategoryDatalist();

  // Setup dynamic tools container with 1 initial row
  const toolsContainer = document.getElementById('toolLinksContainer');
  if (toolsContainer) {
    toolsContainer.innerHTML = '';
    addToolLinkInputRow('Tools 1 (ChatGPT Studio)', '');
  }

  // Setup dynamic video container with 1 initial row
  const vidContainer = document.getElementById('toolVideosContainer');
  if (vidContainer) {
    vidContainer.innerHTML = '';
    addToolVideoInputRow('Video 1: Tutorial Utama', '');
  }

  openModal('toolEditorModal');
}

function openEditToolModal(toolId) {
  const tool = (courseData.portalTools || []).find(t => t.id === toolId);
  if (!tool) return;

  document.getElementById('toolFormId').value = tool.id;
  document.getElementById('toolEditorModalTitle').textContent = 'Edit Tools: ' + tool.name;
  document.getElementById('toolFormName').value = tool.name || '';
  document.getElementById('toolFormCategory').value = tool.category || getOfficialCategory(tool.levelNum, tool.name);
  document.getElementById('toolFormStatus').value = tool.status !== false ? 'true' : 'false';
  document.getElementById('toolFormCoverUrl').value = tool.coverUrl || '';
  previewToolCover(tool.coverUrl || 'https://www.animato.id/cinema/asmr.webp');
  document.getElementById('toolFormToolUrl').value = tool.toolUrl || '';
  document.getElementById('toolFormDesc').value = tool.desc || '';
  if (document.getElementById('toolFormMarkdownPrompt')) document.getElementById('toolFormMarkdownPrompt').value = tool.markdownPrompt || '';
  if (document.getElementById('toolFormInstructionsMd')) {
    document.getElementById('toolFormInstructionsMd').value = tool.instructionsMd || (tool.instructions ? tool.instructions.map((s, idx) => (idx + 1) + '. ' + s).join('\n') : '') || '';
  }

  if (typeof updateCategoryDatalist === 'function') updateCategoryDatalist();

  // Setup dynamic tools container with existing tools
  const toolsContainer = document.getElementById('toolLinksContainer');
  if (toolsContainer) {
    toolsContainer.innerHTML = '';
    let toolList = [];
    if (tool.tools && tool.tools.length > 0) {
      toolList = tool.tools;
    } else if (tool.toolUrl) {
      toolList = [{ name: 'Tools AI Utama', url: tool.toolUrl }];
    }
    if (toolList.length > 0) {
      toolList.forEach(t => addToolLinkInputRow(t.name || t.title || 'Tools AI', t.url));
    } else {
      addToolLinkInputRow('Tools 1 (ChatGPT Studio)', '');
    }
  }

  // Setup dynamic video container with existing videos
  const vidContainer = document.getElementById('toolVideosContainer');
  if (vidContainer) {
    vidContainer.innerHTML = '';
    const videoList = (tool.videos && tool.videos.length > 0)
      ? tool.videos
      : (tool.videoUrl ? [{ title: 'Video Tutorial Utama', url: tool.videoUrl }] : []);

    if (videoList.length > 0) {
      videoList.forEach(v => addToolVideoInputRow(v.title, v.url));
    } else {
      addToolVideoInputRow('Video 1: Tutorial Utama', '');
    }
  }

  openModal('toolEditorModal');
}

function previewToolCover(url) {
  const img = document.getElementById('toolCoverPreviewImg');
  if (img) {
    img.src = url || 'https://www.animato.id/cinema/asmr.webp';
  }
}

function setPresetCover(url) {
  document.getElementById('toolFormCoverUrl').value = url;
  previewToolCover(url);
}

function handleToolFormSubmit(e) {
  e.preventDefault();
  const id = document.getElementById('toolFormId').value.trim();
  const name = document.getElementById('toolFormName').value.trim();
  const category = document.getElementById('toolFormCategory').value.trim();
  const status = document.getElementById('toolFormStatus').value === 'true';
  const coverUrl = document.getElementById('toolFormCoverUrl').value.trim();
  const toolUrl = document.getElementById('toolFormToolUrl').value.trim();
  const desc = document.getElementById('toolFormDesc').value.trim();
  const markdownPrompt = document.getElementById('toolFormMarkdownPrompt') ? document.getElementById('toolFormMarkdownPrompt').value.trim() : '';
  const instructionsMd = document.getElementById('toolFormInstructionsMd') ? document.getElementById('toolFormInstructionsMd').value.trim() : '';

  // Extract all tool link rows
  const toolRows = document.querySelectorAll('.tool-link-row');
  const toolLinks = [];
  toolRows.forEach((row, idx) => {
    const name = row.querySelector('.tool-link-title')?.value?.trim() || `Tools ${idx + 1}`;
    const url = row.querySelector('.tool-link-url')?.value?.trim();
    if (url) {
      toolLinks.push({ name, title: name, url });
    }
  });
  const mainToolUrl = toolLinks.length > 0 ? toolLinks[0].url : (toolUrl || '');

  // Extract all video rows
  const videoRows = document.querySelectorAll('.tool-video-row');
  const videos = [];
  videoRows.forEach((row, idx) => {
    const title = row.querySelector('.tool-video-title')?.value?.trim() || `Part ${idx + 1}`;
    const url = row.querySelector('.tool-video-url')?.value?.trim();
    if (url) {
      videos.push({ title, url });
    }
  });

  const mainVideoUrl = videos.length > 0 ? videos[0].url : '';

  // Match or create categoryId dynamically
  let matchedCat = (courseData.curriculumCategories || []).find(c => (c.name && c.name.toLowerCase() === category.toLowerCase()) || c.id === category);
  if (!matchedCat && category) {
    matchedCat = {
      id: 'cat-' + Date.now(),
      name: category,
      slug: category.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, ''),
      desc: 'Modul materi ' + category,
      icon: 'fa-folder',
      color: '#8b5cf6',
      order: (courseData.curriculumCategories || []).length + 1,
      status: true,
      createdAt: new Date().toISOString()
    };
    if (!courseData.curriculumCategories) courseData.curriculumCategories = [];
    courseData.curriculumCategories.push(matchedCat);
  }
  const assignedCategoryId = matchedCat ? matchedCat.id : 'cat-uncategorized';

  if (!courseData.portalTools) {
    courseData.portalTools = [];
  }

  if (id) {
    // Edit existing
    const existing = courseData.portalTools.find(t => t.id === id);
    if (existing) {
      existing.name = name;
      existing.category = category;
      existing.categoryId = assignedCategoryId;
      existing.status = status;
      existing.coverUrl = coverUrl;
      existing.toolUrl = mainToolUrl;
      existing.tools = toolLinks;
      existing.videos = videos;
      existing.videoUrl = mainVideoUrl;
      existing.desc = desc;
    existing.markdownPrompt = markdownPrompt;
      existing.instructionsMd = instructionsMd;
      if (instructionsMd) {
        const instLines = instructionsMd.split('\n').map(l => l.replace(/^(\d+[\.\)]|\-|\*)\s*/, '').trim()).filter(l => l.length > 0);
        if (instLines.length > 0) existing.instructions = instLines;
      }
    }
    showToast(`Tools "${name}" berhasil diperbarui! (${videos.length} Video tersimpan)`);
  } else {
    // Add new
    const newTool = {
      id: 'tool-' + Date.now(),
      name,
      category,
      status,
      coverUrl: coverUrl || 'https://www.animato.id/cinema/asmr.webp',
      toolUrl: mainToolUrl,
      tools: toolLinks,
      videos,
      videoUrl: mainVideoUrl,
      desc,
      views: 0
    };
    courseData.portalTools.unshift(newTool);
    showToast(`Tools baru "${name}" berhasil ditambahkan! (${videos.length} Video)`);
  }

  // 1. Close modal instantly with zero lag
  closeModal('toolEditorModal');
  const modalEl = document.getElementById('toolEditorModal');
  if (modalEl) {
    modalEl.classList.remove('active');
    modalEl.style.display = 'none';
  }
  document.body.style.overflow = 'auto';

  // 2. Update lastUpdated & persist
  courseData.lastUpdated = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) + ' WIB';
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(courseData));
  } catch (e) {}

  // 3. Re-render instantly
  renderAdminToolsTable();
  if (typeof renderMemberTools === 'function') {
    renderMemberTools();
  }
}


// ----------------------------------------------------
// IMAGE UPLOAD HANDLERS (BASE64 CLIENT-SIDE STORAGE)
// ----------------------------------------------------
function handleToolImageUpload(event) {
  const file = event.target.files[0];
  if (!file) return;

  if (!file.type.startsWith('image/')) {
    alert("Harap pilih file gambar (JPG, PNG, WebP).");
    return;
  }

  const reader = new FileReader();
  reader.onload = function(e) {
    const dataUrl = e.target.result;
    document.getElementById('toolFormCoverUrl').value = dataUrl;
    const previewImg = document.getElementById('toolCoverPreviewImg');
    if (previewImg) previewImg.src = dataUrl;
    showToast("Gambar cover tools berhasil dimuat!");
  };
  reader.readAsDataURL(file);
}

function uploadCategoryCardImage(event, index) {
  const file = event.target.files[0];
  if (!file) return;

  if (!file.type.startsWith('image/')) {
    alert("Harap pilih file gambar (JPG, PNG, WebP).");
    return;
  }

  const reader = new FileReader();
  reader.onload = function(e) {
    const dataUrl = e.target.result;
    // Update preview img
    const previewImg = document.getElementById('catPreviewImg_' + index);
    if (previewImg) previewImg.src = dataUrl;
    // Update hidden input
    const hiddenInput = document.getElementById('editCatImg_' + index);
    if (hiddenInput) hiddenInput.value = dataUrl;
    // Update in data immediately
    if (courseData.categories && courseData.categories[index]) {
      courseData.categories[index].imageUrl = dataUrl;
    }
    showToast(`Gambar kartu #${index + 1} berhasil di-upload!`);
  };
  reader.readAsDataURL(file);
}

function exportPortalToolsJSON() {
  const tools = courseData.portalTools || [];
  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(tools, null, 2));
  const downloadAnchor = document.createElement('a');
  downloadAnchor.setAttribute("href", dataStr);
  downloadAnchor.setAttribute("download", "portal-tools-materi.json");
  document.body.appendChild(downloadAnchor);
  downloadAnchor.click();
  downloadAnchor.remove();
  showToast("File data tools materi berhasil diunduh!");
}

// Real-Time WIB Clock Engine
function tickWibClock() {
  const now = new Date();
  const timeFull = now.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit', timeZone: 'Asia/Jakarta' }).replace(/\./g, ':') + ' WIB';
  const timeShort = now.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Jakarta' }).replace(/\./g, ':') + ' WIB';
  const clockEl = document.getElementById('liveMemberClock');
  if (clockEl) clockEl.textContent = timeFull;
  const navClockEl = document.getElementById('liveNavClock');
  if (navClockEl) navClockEl.textContent = timeShort;
}

// DOM Ready
document.addEventListener('DOMContentLoaded', () => {
  // Start Real-Time Live Clock Immediately
  tickWibClock();
  setInterval(tickWibClock, 1000);

  if (isMemberUnlocked && document.body) document.body.classList.add('member-portal-mode');
  initTheme();
  initData();
  renderAll();
  setTimeout(() => {
    if (typeof syncFromGasDatabase === 'function') syncFromGasDatabase(true);
  }, 1000);
  if (isMemberUnlocked && typeof startMemberSessionTimer === 'function') {
    startMemberSessionTimer();
  }

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      closeModal('previewModal');
      closeModal('editorModal');
      closeModal('checkoutModal');
      closeModal('loginModal');
      closeModal('toolEditorModal');
      closeVideoModal();
      closePortalAdmin();
    }
    // Secret keyboard shortcut to open Admin: Ctrl + Shift + A or Ctrl + M
    if ((e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'a') || (e.ctrlKey && e.key.toLowerCase() === 'm')) {
      e.preventDefault();
      openPortalAdmin();
      showToast("Membuka Portal Pengelola...");
    }
  });

  // Check URL Hash for secret admin access (#admin or #portal)
  if (window.location.hash === '#admin' || window.location.hash === '#portal') {
    closeModal('loginModal');
    setTimeout(openPortalAdmin, 300);
  } else {
    // Tangani parameter dari email: ?redeem=1 atau ?login=1 atau ?code=
        const urlParams = new URLSearchParams(window.location.search);
    const isRedeemMode = urlParams.has('redeem') || urlParams.has('login') || urlParams.has('code');
    const emailFromUrl = urlParams.get('email');
    const codeFromUrl = urlParams.get('code');

    if (isRedeemMode) {
      // Sesuai instruksi: Setelah member dapat kode via WA/email, saat link diklik WAJIB masukkan kode unik & email dulu (TIDAK BOLEH langsung tembus web)!
      isMemberUnlocked = false;
      localStorage.removeItem('creator_class_member_unlocked');
      localStorage.removeItem('creator_class_active_code');
      localStorage.removeItem('creator_class_session_timeout');
      if (typeof updateMemberAccessUI === 'function') updateMemberAccessUI();

      // Buka modal login langsung di Tab Member dan Tampilan Masukkan Kode Unik & Email (Redeem View)
      openModal('loginModal');
      switchLoginModalTab('member');
      toggleRedeemView(true);

      const emailInput = document.getElementById('redeemEmailInput');
      const codeInput = document.getElementById('redeemCodeInput');
      if (emailInput && emailFromUrl) emailInput.value = decodeURIComponent(emailFromUrl);
      if (codeInput && codeFromUrl) codeInput.value = decodeURIComponent(codeFromUrl);

      setTimeout(() => {
        if (codeInput && !codeFromUrl) {
          codeInput.focus();
        } else if (emailInput && !emailFromUrl) {
          emailInput.focus();
        } else {
          const btnSubmit = document.getElementById('btnSubmitRedeem');
          if (btnSubmit) btnSubmit.focus();
        }
      }, 350);

      showToast("Silakan periksa Kode Aktivasi & Email Anda, lalu klik 'Buka Akses'!");
    } else {
      // Kunjungan biasa tanpa parameter aktivasi
      const modal = document.getElementById('loginModal');
      if (modal) {
        if (isMemberUnlocked) {
          modal.classList.remove('active');
          modal.style.display = 'none';
          modal.classList.add('hidden');
          if (document.body) document.body.style.overflow = 'auto';
        } else {
          // Jika belum unlock dan membuka #materi, langsung tampilkan modal redeem
          if (window.location.hash === '#materi') {
            openModal('loginModal');
            switchLoginModalTab('member');
            toggleRedeemView(true);
          }
        }
      }
      updateMemberAccessUI();
    }
  }

  window.addEventListener('hashchange', () => {
    if (window.location.hash === '#admin' || window.location.hash === '#portal') {
      openPortalAdmin();
    } else if (window.location.hash === '#login') {
      openLoginModal();
    }
  });
});

// ----------------------------------------------------
// TESTIMONIALS LOGIC (DUA VERSI: MEMBER WEB & ADMIN PORTAL)
// ----------------------------------------------------
function renderTestimonials() {
  const container = document.getElementById('testimonialsGrid');
  if (courseData.sectionHeaders) {
    const tTitle = document.getElementById('testimoniSectionTitle');
    if (tTitle && courseData.sectionHeaders.testimoniTitle) tTitle.textContent = courseData.sectionHeaders.testimoniTitle;
    const tDesc = document.getElementById('testimoniSectionDesc');
    if (tDesc && courseData.sectionHeaders.testimoniDesc) tDesc.textContent = courseData.sectionHeaders.testimoniDesc;
  }
  const allItems = courseData.testimonials || (window.DEFAULT_COURSE_DATA && window.DEFAULT_COURSE_DATA.testimonials) || [];
  const items = allItems.filter(t => !t.isTakedown);
  if (!container) return;

  container.innerHTML = items.map(t => {
    const stars = Array(Number(t.rating) || 5).fill('<i class="fa-solid fa-star text-amber-400 text-xs"></i>').join('');
    
    // Optional photo proof attachment
    let photoHtml = '';
    if (t.photoProofUrl) {
      photoHtml = `
        <div class="mt-3 rounded-2xl overflow-hidden border border-purple-500/20 bg-slate-900 relative group/thumb">
          <img src="${t.photoProofUrl}" alt="Karya ${t.name}" class="w-full h-36 object-cover group-hover/thumb:scale-105 transition-transform duration-300" loading="lazy">
          <span class="absolute top-2 left-2 px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-purple-950/85 text-purple-200 border border-purple-500/40 backdrop-blur-xs flex items-center gap-1">
            <i class="fa-solid fa-wand-magic-sparkles text-amber-300"></i> Karya Alumni
          </span>
        </div>
      `;
    }

    // Optional video proof link
    let videoHtml = '';
    if (t.videoProofUrl) {
      videoHtml = `
        <div class="mt-3">
          <a href="${t.videoProofUrl}" target="_blank" rel="noopener noreferrer" class="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-purple-600/15 hover:bg-purple-600/25 border border-purple-500/30 text-purple-600 dark:text-purple-300 text-xs font-semibold transition-all">
            <i class="fa-brands fa-youtube text-red-500"></i>
            <span>Tonton Video Karya</span>
            <i class="fa-solid fa-arrow-up-right-from-square text-[10px] opacity-70"></i>
          </a>
        </div>
      `;
    }

    return `
      <div class="p-6 rounded-3xl bg-white dark:bg-[#161722] border border-slate-200/80 dark:border-white/10 shadow-lg flex flex-col justify-between hover:-translate-y-1 transition-all">
        <div>
          <div class="flex items-center justify-between mb-4">
            <div class="flex items-center gap-1">${stars}</div>
            <span class="px-2.5 py-0.5 rounded-full text-[10px] font-mono font-bold bg-purple-500/10 text-purple-600 dark:text-purple-400 border border-purple-500/20">
              ${t.tag || 'Member'}
            </span>
          </div>
          <p class="text-xs sm:text-sm text-slate-700 dark:text-slate-300 leading-relaxed italic mb-4">
            "${t.story}"
          </p>
          ${photoHtml}
          ${videoHtml}
        </div>
        <div class="flex items-center gap-3 pt-4 border-t border-slate-100 dark:border-white/5 mt-4">
          <img src="${t.avatar || 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=150'}" alt="${t.name}" class="w-10 h-10 rounded-full object-cover border border-purple-500/30 shrink-0">
          <div class="min-w-0">
            <h4 class="font-bold text-xs sm:text-sm text-slate-900 dark:text-white leading-tight truncate">${t.name}</h4>
            <p class="text-[11px] text-slate-400 mt-0.5 truncate">${t.role}</p>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

// VERSI 1: MEMBER MANUAL DARI WEB (MODAL + OPTIONAL PHOTO & VIDEO)
function openMemberTestimonialModal() {
  const memberName = getActiveMemberInfo() || localStorage.getItem('creator_class_member_name') || '';
  const nameInput = document.getElementById('testiName');
  if (nameInput) {
    if (memberName && !nameInput.value) {
      nameInput.value = memberName;
    }
  }

  // Clear photo and video
  removeTestiPhotoProof();
  const vidInput = document.getElementById('testiVideoProofUrl');
  if (vidInput) vidInput.value = '';

  openModal('addTestimonialModal');
}

function handleTestiPhotoProofUpload(event) {
  const file = event.target.files && event.target.files[0];
  if (!file) return;

  if (file.size > 2 * 1024 * 1024) {
    alert("Ukuran gambar terlalu besar. Maksimal 2MB.");
    event.target.value = '';
    return;
  }

  const reader = new FileReader();
  reader.onload = function(e) {
    const dataUrl = e.target.result;
    const hiddenInput = document.getElementById('testiPhotoProofUrl');
    if (hiddenInput) hiddenInput.value = dataUrl;

    const previewBox = document.getElementById('testiPhotoPreview');
    const previewImg = document.getElementById('testiPhotoPreviewImg');
    if (previewImg) previewImg.src = dataUrl;
    if (previewBox) previewBox.classList.remove('hidden');
  };
  reader.readAsDataURL(file);
}

function removeTestiPhotoProof() {
  const hiddenInput = document.getElementById('testiPhotoProofUrl');
  if (hiddenInput) hiddenInput.value = '';

  const fileInput = document.getElementById('testiPhotoFileInput');
  if (fileInput) fileInput.value = '';

  const previewBox = document.getElementById('testiPhotoPreview');
  const previewImg = document.getElementById('testiPhotoPreviewImg');
  if (previewImg) previewImg.src = '';
  if (previewBox) previewBox.classList.add('hidden');
}

function handleAddTestimonialSubmit(e) {
  e.preventDefault();
  const name = document.getElementById('testiName')?.value?.trim();
  const role = document.getElementById('testiRole')?.value?.trim();
  const tag = document.getElementById('testiTag')?.value?.trim();
  const story = document.getElementById('testiStory')?.value?.trim();
  const rating = Number(document.getElementById('testiRatingVal')?.value || 5);
  const photoProofUrl = document.getElementById('testiPhotoProofUrl')?.value || '';
  const videoProofUrl = document.getElementById('testiVideoProofUrl')?.value?.trim() || '';

  if (!name || !story) {
    alert("Harap isi nama dan cerita pengalaman Anda.");
    return;
  }

  const newTesti = {
    id: "testi-" + Date.now(),
    name: name,
    role: role || "Member CREATOR CLASS",
    avatar: "https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=150&auto=format&fit=crop&q=80",
    rating: rating,
    story: story,
    tag: tag || "Kisah Member",
    photoProofUrl: photoProofUrl,
    videoProofUrl: videoProofUrl
  };

  if (!courseData.testimonials) courseData.testimonials = [];
  courseData.testimonials.unshift(newTesti);
  
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(courseData));
  } catch (err) {
    console.warn("Storage save error:", err);
  }

  closeModal('addTestimonialModal');
  e.target.reset();
  removeTestiPhotoProof();
  renderTestimonials();
  renderAdminTestimonialsTable();
  showToast("🎉 Terima kasih! Testimoni & hasil karya Anda langsung tayang!");
}

// ----------------------------------------------------
// VERSI 2: ADMIN KELOLA TESTIMONI (DI PORTAL PENGELOLA)
// ----------------------------------------------------
function renderAdminTestimonialsTable() {
  const tbody = document.getElementById('adminTestimonialsTableBody');
  if (!tbody) return;

  const items = courseData.testimonials || (window.DEFAULT_COURSE_DATA && window.DEFAULT_COURSE_DATA.testimonials) || [];
  if (items.length === 0) {
    tbody.innerHTML = `<tr><td colspan="6" class="text-center py-6 text-slate-600 dark:text-slate-400">Belum ada testimoni. Klik "+ Tambah Testimoni Baru" untuk menambahkan.</td></tr>`;
    return;
  }

  tbody.innerHTML = items.map(t => {
    const stars = Array(Number(t.rating) || 5).fill('<i class="fa-solid fa-star text-amber-400 text-[10px]"></i>').join('');
    
    let proofsBadge = '<span class="text-slate-500 text-[11px]">-</span>';
    const badges = [];
    if (t.photoProofUrl) {
      badges.push(`<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] bg-purple-500/20 text-purple-300 border border-purple-500/30"><i class="fa-solid fa-image"></i> Foto</span>`);
    }
    if (t.videoProofUrl) {
      badges.push(`<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] bg-red-500/20 text-red-300 border border-red-500/30"><i class="fa-brands fa-youtube"></i> Video</span>`);
    }
    if (badges.length > 0) proofsBadge = badges.join(' ');

    const snippet = (t.story || '').length > 70 ? (t.story || '').substring(0, 70) + '...' : (t.story || '');

    const isTakedown = !!t.isTakedown;
    const statusBadge = isTakedown 
      ? `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-500/20 text-amber-300 border border-amber-500/30 whitespace-nowrap"><i class="fa-solid fa-eye-slash mr-1"></i>Takedown</span>`
      : `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-500/20 text-emerald-300 border border-emerald-500/30 whitespace-nowrap"><i class="fa-solid fa-circle-check mr-1"></i>Tayang</span>`;

    const takedownBtn = isTakedown
      ? `<button type="button" onclick="toggleTakedownTestimonial('${t.id}')" class="p-1.5 rounded-lg bg-emerald-500/20 hover:bg-emerald-600 text-emerald-300 hover:text-white transition-all text-xs" title="Publikasikan Kembali ke Website"><i class="fa-solid fa-eye"></i></button>`
      : `<button type="button" onclick="toggleTakedownTestimonial('${t.id}')" class="p-1.5 rounded-lg bg-amber-500/20 hover:bg-amber-600 text-amber-300 hover:text-white transition-all text-xs" title="Takedown Testimoni (Sembunyikan dari Website)"><i class="fa-solid fa-eye-slash"></i></button>`;

    return `
      <tr class="hover:bg-white/5 transition-colors">
        <td class="py-3 px-3">
          <div class="flex items-center gap-2">
            <img src="${t.avatar || 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=150'}" alt="${t.name}" class="w-8 h-8 rounded-full object-cover border border-purple-500/30 shrink-0">
            <div>
              <div class="font-bold text-white leading-tight">${t.name}</div>
              <div class="text-[10px] text-purple-400">${t.tag || 'Member'}</div>
            </div>
          </div>
        </td>
        <td class="py-3 px-3 text-slate-300">${t.role || '-'}</td>
        <td class="py-3 px-3"><div class="flex items-center gap-0.5">${stars}</div></td>
        <td class="py-3 px-3 text-slate-300 max-w-xs truncate" title="${t.story || ''}">"${snippet}"</td>
        <td class="py-3 px-3">${proofsBadge}</td>
        <td class="py-3 px-3 text-center">${statusBadge}</td>
        <td class="py-3 px-3 text-center">
          <div class="flex items-center justify-center gap-1.5">
            ${takedownBtn}
            <button type="button" onclick="openEditAdminTestimonialModal('${t.id}')" class="p-1.5 rounded-lg bg-white/10 hover:bg-purple-600 text-slate-300 hover:text-white transition-all text-xs" title="Edit Testimoni">
              <i class="fa-solid fa-pen-to-square"></i>
            </button>
            <button type="button" onclick="deleteTestimonial('${t.id}')" class="p-1.5 rounded-lg bg-rose-500/20 hover:bg-rose-600 text-rose-300 hover:text-white transition-all text-xs" title="Hapus Testimoni">
              <i class="fa-solid fa-trash"></i>
            </button>
          </div>
        </td>
      </tr>
    `;
  }).join('');
}

function toggleTakedownTestimonial(id) {
  if (!courseData.testimonials) courseData.testimonials = [];
  const t = courseData.testimonials.find(item => String(item.id) === String(id));
  if (!t) return;

  t.isTakedown = !t.isTakedown;

  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(courseData));
  } catch (err) {
    console.warn("Storage save error:", err);
  }

  renderAdminTestimonialsTable();
  renderTestimonials();

  if (t.isTakedown) {
    showToast("⛔ Testimoni berhasil di-takedown dari website!");
  } else {
    showToast("✅ Testimoni berhasil ditayangkan kembali!");
  }
}

function openAdminAddTestimonialModal() {
  document.getElementById('adminTestiId').value = '';
  document.getElementById('adminTestiName').value = '';
  document.getElementById('adminTestiRole').value = '';
  document.getElementById('adminTestiTag').value = '';
  document.getElementById('adminTestiRating').value = '5';
  document.getElementById('adminTestiAvatar').value = '';
  document.getElementById('adminTestiStory').value = '';
  document.getElementById('adminTestiPhotoProof').value = '';
  document.getElementById('adminTestiVideoProof').value = '';
  document.getElementById('adminTestiModalTitle').textContent = 'Tambah Testimoni Baru (Admin)';
  openModal('adminTestimonialModal');
}

function openEditAdminTestimonialModal(id) {
  const items = courseData.testimonials || [];
  const t = items.find(item => String(item.id) === String(id));
  if (!t) return;

  document.getElementById('adminTestiId').value = t.id || '';
  document.getElementById('adminTestiName').value = t.name || '';
  document.getElementById('adminTestiRole').value = t.role || '';
  document.getElementById('adminTestiTag').value = t.tag || '';
  document.getElementById('adminTestiRating').value = String(t.rating || 5);
  document.getElementById('adminTestiAvatar').value = t.avatar || '';
  document.getElementById('adminTestiStory').value = t.story || '';
  document.getElementById('adminTestiPhotoProof').value = t.photoProofUrl || '';
  document.getElementById('adminTestiVideoProof').value = t.videoProofUrl || '';
  document.getElementById('adminTestiModalTitle').textContent = 'Edit Testimoni Alumni';
  openModal('adminTestimonialModal');
}

function handleAdminPhotoProofUpload(event) {
  const file = event.target.files && event.target.files[0];
  if (!file) return;

  if (file.size > 2 * 1024 * 1024) {
    alert("Ukuran gambar terlalu besar. Maksimal 2MB.");
    event.target.value = '';
    return;
  }

  const reader = new FileReader();
  reader.onload = function(e) {
    const input = document.getElementById('adminTestiPhotoProof');
    if (input) input.value = e.target.result;
    showToast("Foto karya berhasil dimuat!");
  };
  reader.readAsDataURL(file);
}

function saveAdminTestimonialModal(event) {
  event.preventDefault();
  const id = document.getElementById('adminTestiId').value.trim();
  const name = document.getElementById('adminTestiName').value.trim();
  const role = document.getElementById('adminTestiRole').value.trim();
  const tag = document.getElementById('adminTestiTag').value.trim();
  const rating = Number(document.getElementById('adminTestiRating').value || 5);
  const avatar = document.getElementById('adminTestiAvatar').value.trim() || 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=150';
  const story = document.getElementById('adminTestiStory').value.trim();
  const photoProofUrl = document.getElementById('adminTestiPhotoProof').value.trim();
  const videoProofUrl = document.getElementById('adminTestiVideoProof').value.trim();

  if (!courseData.testimonials) courseData.testimonials = [];

  if (id) {
    // Edit existing
    const idx = courseData.testimonials.findIndex(item => String(item.id) === String(id));
    if (idx !== -1) {
      courseData.testimonials[idx] = {
        ...courseData.testimonials[idx],
        name, role, tag, rating, avatar, story, photoProofUrl, videoProofUrl
      };
    }
  } else {
    // Create new
    const newTesti = {
      id: "testi-" + Date.now(),
      name, role, tag: tag || "Kisah Alumni", rating, avatar, story, photoProofUrl, videoProofUrl
    };
    courseData.testimonials.unshift(newTesti);
  }

  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(courseData));
  } catch (err) {
    console.warn("Storage save error:", err);
  }

  closeModal('adminTestimonialModal');
  renderAdminTestimonialsTable();
  renderTestimonials();
  showToast("✅ Seketika tersimpan! Testimoni berhasil diperbarui.");
}

function deleteTestimonial(id) {
  if (!confirm("Hapus testimoni ini secara permanen dari landing page?")) return;
  
  if (!courseData.testimonials) courseData.testimonials = [];
  courseData.testimonials = courseData.testimonials.filter(item => String(item.id) !== String(id));

  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(courseData));
  } catch (err) {
    console.warn("Storage save error:", err);
  }

  renderAdminTestimonialsTable();
  renderTestimonials();
  showToast("✅ Seketika dihapus! Testimoni telah dihapus dari landing page.");
}

