function renderSingleMemberToolCard(t) {
  const cover = t.coverUrl || 'assets/covers/' + t.id + '.jpg';
  const videoList = (t.videos && t.videos.length > 0) ? t.videos : (t.videoUrl ? [{ title: t.name, url: t.videoUrl }] : []);
  const hasVideo = videoList.length > 0;
  
  // Tools logic
  const toolList = (t.tools && t.tools.length > 0) ? t.tools : (t.toolUrl && !t.toolUrl.includes('notion.so') ? [{ url: t.toolUrl, title: 'Link Tools' }] : []);
  const hasTool = toolList.length > 0;
  let primaryToolUrl = hasTool ? toolList[0].url.trim() : '';
  if (primaryToolUrl && !/^https?:\/\//i.test(primaryToolUrl)) {
    primaryToolUrl = 'https://' + primaryToolUrl;
  }

  const hasInstructions = t.instructions && t.instructions.length > 0;
  const hasPrompt = !!t.markdownPrompt && t.markdownPrompt.trim().length > 0;
  const promptLineCount = hasPrompt ? t.markdownPrompt.split('\n').filter(l => l.trim().length > 0).length : 0;
  const instructionCount = hasInstructions ? t.instructions.length : 0;

  return `
    <div class="member-tool-card flex flex-col p-4 sm:p-5 group bg-white dark:bg-[#14151c] rounded-2xl border border-slate-200 dark:border-white/10 shadow-sm hover:shadow-2xl hover:border-purple-500/40 transition-all duration-300">
      <!-- Thumbnail & Badges -->
      <div class="relative w-full aspect-video rounded-xl overflow-hidden bg-slate-900 mb-4 cursor-pointer" onclick="${hasPrompt ? `openPromptMarkdownModal('${t.id}')` : `openInstructionsModal('${t.id}')`}">
        <img src="${cover}" alt="${t.name}" class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" loading="lazy">
        <div class="absolute inset-0 bg-gradient-to-t from-black/85 via-black/30 to-transparent"></div>
        
        <!-- Category Badge -->
        <div class="absolute top-2.5 left-2.5">
          <span class="px-2.5 py-1 rounded-full text-[10px] font-mono font-bold bg-black/70 backdrop-blur-md text-purple-300 border border-white/10 uppercase tracking-wider">
            ${t.category || 'Materi'}
          </span>
        </div>

        <!-- Video Pill -->
        ${hasVideo ? `
          <div class="absolute bottom-2.5 right-2.5 px-2.5 py-1 rounded-lg bg-black/80 backdrop-blur-sm text-[10px] font-mono font-bold text-white flex items-center gap-1.5 border border-purple-500/30">
            <i class="fa-solid fa-circle-play text-purple-400 text-xs"></i> ${videoList.length} Video
          </div>
        ` : `
          <div class="absolute bottom-2.5 right-2.5 px-2.5 py-1 rounded-lg bg-black/80 backdrop-blur-sm text-[10px] font-mono font-bold text-emerald-300 flex items-center gap-1.5 border border-emerald-500/30">
            <i class="fa-solid fa-terminal text-xs"></i> Prompt MD
          </div>
        `}
      </div>

      <!-- Details -->
      <div class="flex-1 flex flex-col">
        <div class="flex items-center justify-between gap-2 mb-1.5">
          <span class="text-[11px] font-mono font-bold text-purple-400 tracking-wider uppercase">
            ${t.levelNum >= 0 ? 'LEVEL ' + t.levelNum : 'MODUL'}
          </span>
          <span class="text-[10px] text-slate-500 font-mono flex items-center gap-1">
            <i class="fa-solid fa-eye text-[9px]"></i> ${t.views || 35}x
          </span>
        </div>

        <h3 class="font-heading text-base font-bold text-slate-900 dark:text-white group-hover:text-purple-400 transition-colors line-clamp-2 mb-2 leading-snug">
          ${t.name}
        </h3>

        <p class="text-xs text-slate-600 dark:text-slate-400 line-clamp-2 mb-3 flex-1 leading-relaxed">
          ${t.desc}
        </p>

        <!-- Metadata Baris Prompt & Jumlah Instruksi -->
        <div class="flex items-center justify-between text-[11px] text-slate-500 dark:text-slate-400 font-mono mb-3.5 pt-2.5 border-t border-slate-100 dark:border-white/5">
          <span class="flex items-center gap-1.5">
            <i class="fa-solid fa-terminal text-purple-400"></i> Prompt: ${promptLineCount} Baris
          </span>
          <span class="flex items-center gap-1.5">
            <i class="fa-solid fa-list-check text-blue-400"></i> ${instructionCount} Langkah
          </span>
        </div>

        <!-- Action Buttons: Strict separation between Prompt MD, Instruksi, Video, Tools -->
        <div class="flex flex-col gap-2 pt-1">
          <!-- Row 1: Prompt MD & Instruksi -->
          <div class="grid grid-cols-2 gap-2">
            ${hasPrompt ? `
              <button onclick="openPromptMarkdownModal('${t.id}')" class="py-2.5 px-2.5 rounded-xl bg-purple-600 hover:bg-purple-700 active:scale-[0.98] text-white text-xs font-bold transition-all shadow-md shadow-purple-600/30 flex items-center justify-center gap-1.5 cursor-pointer" title="Buka Naskah Prompt AI (Markdown)">
                <i class="fa-solid fa-terminal text-[11px]"></i>
                <span>Prompt MD</span>
              </button>
              <button onclick="openInstructionsModal('${t.id}')" class="py-2.5 px-2.5 rounded-xl bg-blue-600/20 hover:bg-blue-600 text-blue-300 hover:text-white border border-blue-500/40 active:scale-[0.98] text-xs font-bold transition-all flex items-center justify-center gap-1.5 cursor-pointer" title="Buka Panduan Langkah Praktik">
                <i class="fa-solid fa-list-check text-[11px]"></i>
                <span>Instruksi</span>
              </button>
            ` : `
              <button onclick="openInstructionsModal('${t.id}')" class="col-span-2 py-2.5 px-3 rounded-xl bg-gradient-to-r from-blue-600/30 to-indigo-600/30 hover:from-blue-600/40 hover:to-indigo-600/40 border border-blue-500/50 text-blue-200 hover:text-white active:scale-[0.98] text-xs font-bold transition-all flex items-center justify-center gap-2 cursor-pointer shadow-sm" title="Buka Arahan & Panduan Praktik Lengkap">
                <i class="fa-solid fa-list-check text-xs text-blue-400"></i>
                <span>Instruksi & Panduan Praktik</span>
              </button>
            `}
          </div>

          <!-- Row 2: Tonton Video & Link Tools -->
          <div class="flex items-center gap-2">
            ${hasVideo ? `
              <button onclick="openVideoModal('${t.id}')" class="${hasTool ? 'flex-1' : 'w-full'} py-2 px-3 rounded-xl bg-slate-100 dark:bg-white/10 hover:bg-slate-200 dark:hover:bg-white/15 active:scale-[0.98] text-slate-700 dark:text-slate-200 text-xs font-semibold transition-all flex items-center justify-center gap-1.5 cursor-pointer" title="Tonton Video Tutorial">
                <i class="fa-solid fa-circle-play text-[11px] text-purple-400"></i>
                <span>Tonton Video ${videoList.length > 1 ? `(${videoList.length})` : ''}</span>
              </button>
            ` : ''}

            ${hasTool ? `
              ${toolList.length > 1 ? `
                <button onclick="openToolPickerModal('${t.id}')" class="flex-1 py-2 px-3 rounded-xl bg-amber-500/15 hover:bg-amber-500/25 active:scale-[0.98] text-amber-300 border border-amber-500/40 text-xs font-bold transition-all flex items-center justify-center gap-1.5 cursor-pointer shadow-sm" title="Buka Pilihan Tools AI">
                  <i class="fa-solid fa-screwdriver-wrench text-[11px] text-amber-400"></i>
                  <span>Pilih Tools (${toolList.length})</span>
                </button>
              ` : `
                <a href="${primaryToolUrl}" target="_blank" rel="noopener noreferrer" class="flex-1 py-2 px-3 rounded-xl bg-amber-500/15 hover:bg-amber-500/25 active:scale-[0.98] text-amber-300 border border-amber-500/40 text-xs font-bold transition-all flex items-center justify-center gap-1.5 shadow-sm" title="Buka Tools / ChatGPT Studio">
                  <i class="fa-solid fa-arrow-up-right-from-square text-[11px] text-amber-400"></i>
                  <span>Buka Tools</span>
                </a>
              `}
            ` : ''}
          </div>
        </div>
      </div>
    </div>
  `;
}

function renderMemberTools() {
  const container = document.getElementById('memberToolsGrid');
  const filtersContainer = document.getElementById('memberCategoryFilters');
  const memberBarContainer = document.getElementById('memberWelcomeBarContainer');
  if (!container) return;

  // Make sure memberToolsGrid is visible and not hidden
  container.classList.remove('hidden');

  initCourseCategoriesAndMigration();

  let tools = courseData.portalTools || (window.DEFAULT_COURSE_DATA && window.DEFAULT_COURSE_DATA.portalTools) || [];
  if (!tools || tools.length < 50 || !tools.some(t => t.id && t.id.startsWith('lvl-'))) {
    tools = JSON.parse(JSON.stringify((window.DEFAULT_COURSE_DATA && window.DEFAULT_COURSE_DATA.portalTools) || []));
    courseData.portalTools = tools;
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(courseData));
    } catch (e) {}
  }

  const notionHubContainer = document.getElementById('notionModuleHubContainer');
  const portalFooter = document.querySelector('.member-portal-footer');

  // Update personalized Member Welcome & Update Bar
  if (memberBarContainer) {
    if (isMemberUnlocked) {
      const { activeCode, memberName, lastUpdated } = getActiveMemberInfo();
      const initials = (memberName || 'MB').split(' ').map(w => w[0]).join('').substring(0, 2).toUpperCase() || 'MB';
      memberBarContainer.innerHTML = `
        <div class="mb-6 p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-[#1c1830] via-[#151324] to-[#0f0d1a] border border-purple-500/40 shadow-xl flex flex-col sm:flex-row sm:items-center justify-between gap-4 text-white">
          <div class="flex items-center gap-3">
            <div class="w-11 h-11 rounded-2xl bg-gradient-to-br from-purple-500 to-indigo-600 text-white flex items-center justify-center font-extrabold text-sm shadow-md shadow-purple-600/30 shrink-0">
              ${initials}
            </div>
            <div>
              <div class="flex items-center gap-2 flex-wrap">
                <span class="text-xs text-slate-200">Selamat Belajar,</span>
                <span class="text-sm font-extrabold text-white tracking-wide" style="color: #ffffff !important;">${memberName}</span>
                <span class="px-2.5 py-0.5 rounded-full text-[10px] font-mono font-bold bg-emerald-500/20 text-emerald-300 border border-emerald-500/40 flex items-center gap-1 shadow-sm">
                  <i class="fa-solid fa-circle-check text-[9px] text-emerald-400"></i> VIP AKTIF
                </span>
              </div>
              <div class="text-xs text-slate-300 mt-1 flex items-center gap-1.5 flex-wrap">
                <span>Kode Aktivasi:</span>
                <span class="font-mono text-amber-300 font-black bg-amber-400/15 px-2.5 py-0.5 rounded border border-amber-400/40 tracking-wider shadow-inner" style="color: #ffd700 !important;">${activeCode || 'IRT-VIP'}</span>
              </div>
            </div>
          </div>
          <div class="flex items-center gap-2.5 self-start sm:self-center mt-1 sm:mt-0">
            <div class="flex items-center gap-2 px-3 py-1.5 rounded-xl bg-black/60 border border-white/10 text-xs font-mono text-slate-200">
              <i class="fa-regular fa-clock text-emerald-400 animate-pulse"></i>
              <span>Waktu: <strong id="liveMemberClock" class="text-emerald-300 font-bold" style="color: #34d399 !important;">${lastUpdated}</strong></span>
            </div>
            <button onclick="handleMemberLogout()" class="px-3.5 py-1.5 rounded-xl bg-rose-500/10 hover:bg-rose-500/20 border border-rose-500/30 text-rose-300 hover:text-rose-200 text-xs font-semibold transition-all inline-flex items-center gap-1.5 cursor-pointer active:scale-95" title="Kunci Akun / Keluar">
              <i class="fa-solid fa-arrow-right-from-bracket text-[10px]"></i> Keluar
            </button>
          </div>
        </div>
      `;
      memberBarContainer.classList.remove('hidden');
    } else {
      memberBarContainer.innerHTML = '';
      memberBarContainer.classList.add('hidden');
    }
  }

  // Render Featured Notion Learning Hub Card
  if (notionHubContainer) {
    if (isMemberUnlocked) {
      notionHubContainer.innerHTML = `
        <div class="relative rounded-3xl overflow-hidden bg-gradient-to-br from-[#18142a] via-[#131122] to-[#0d0c18] border border-purple-500/45 shadow-2xl p-4 sm:p-6 md:p-8 text-white max-w-full">
          <div class="relative z-10 space-y-4 sm:space-y-5">
            <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
              <div>
                <span class="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-gradient-to-r from-pink-500/20 to-purple-500/20 border border-pink-500/30 text-pink-300 text-[11px] font-bold uppercase tracking-wider">
                  <i class="fa-solid fa-crown text-amber-400"></i> Silabus Resmi IRT Naik Level
                </span>
                <h3 class="font-heading text-lg sm:text-2xl md:text-3xl font-black text-white mt-2 tracking-tight" style="color: #ffffff !important; text-shadow: 0 2px 10px rgba(0,0,0,0.6);">
                  Daftar Lengkap 60 Level Materi Animasi AI
                </h3>
                <p class="text-xs sm:text-sm text-slate-200 mt-1 font-medium" style="color: #e2e8f0 !important;">
                  Kurikulum terstruktur dari nol hingga mahir membuat video animasi komersial & affiliate.
                </p>
              </div>

              <div class="flex items-center gap-2 shrink-0">
                <button onclick="openSyllabusModal()" class="px-4 py-2.5 rounded-xl bg-purple-600 hover:bg-purple-500 text-white text-xs font-bold transition-all shadow-md shadow-purple-600/30 flex items-center gap-2 cursor-pointer">
                  <i class="fa-solid fa-list-ol"></i>
                  <span>Daftar Pustaka (0-60)</span>
                </button>
                <button onclick="openLightboxInfographic()" class="px-3.5 py-2.5 rounded-xl bg-white/10 hover:bg-white/15 text-white text-xs font-semibold transition-all flex items-center gap-1.5 cursor-pointer border border-white/15" title="Perbesar Gambar Infografis">
                  <i class="fa-solid fa-magnifying-glass-plus text-purple-300"></i>
                  <span class="hidden md:inline">Perbesar</span>
                </button>
              </div>
            </div>

            <div class="relative rounded-2xl overflow-hidden border border-white/10 shadow-xl group cursor-pointer bg-black/40" onclick="openLightboxInfographic()">
              <img src="assets/daftar_60_level_materi.webp" alt="Daftar Lengkap 60 Level Materi Animasi AI IRT Naik Level" class="w-full h-auto object-cover group-hover:scale-[1.01] transition-transform duration-500" loading="lazy">
              <div class="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                <span class="px-4 py-2 rounded-xl bg-black/80 backdrop-blur-md text-white text-xs font-bold border border-white/20 shadow-lg flex items-center gap-2">
                  <i class="fa-solid fa-expand text-purple-400"></i> Klik untuk Melihat Ukuran Penuh
                </span>
              </div>
            </div>
          </div>
        </div>
      `;
      notionHubContainer.classList.remove('hidden');
    } else {
      notionHubContainer.innerHTML = '';
      notionHubContainer.classList.add('hidden');
    }
  }

  if (portalFooter) {
    if (isMemberUnlocked) {
      portalFooter.classList.remove('hidden');
    } else {
      portalFooter.classList.add('hidden');
    }
  }

  // VIP Lock Gate
  if (!isMemberUnlocked) {
    if (filtersContainer) filtersContainer.innerHTML = '';
    container.innerHTML = `
      <div class="col-span-full max-w-2xl mx-auto w-full p-6 sm:p-10 rounded-3xl bg-[#14151c] border border-amber-500/30 shadow-2xl text-center space-y-6">
        <div class="w-16 h-16 rounded-2xl bg-gradient-to-br from-amber-500/20 to-orange-600/30 border border-amber-500/40 text-amber-400 flex items-center justify-center text-3xl mx-auto shadow-lg shadow-amber-500/20">
          <i class="fa-solid fa-lock"></i>
        </div>
        
        <div>
          <span class="px-3 py-1 rounded-full text-xs font-mono font-bold bg-amber-500/10 text-amber-400 border border-amber-500/30 uppercase tracking-wider">
            Area Khusus Member Terdaftar
          </span>
          <h3 class="font-heading text-2xl sm:text-3xl font-extrabold text-white mt-3">
            Materi Kelas & Video Tutorial Terkunci
          </h3>
          <p class="text-sm text-slate-700 dark:text-slate-200 mt-2 max-w-lg mx-auto">
            Seluruh video tutorial langkah demi langkah, prompt rahasia, dan Custom GPT Studio hanya dapat diakses oleh member yang telah memasukkan Kode Aktivasi.
          </p>
        </div>

        <div class="flex flex-col sm:flex-row items-center justify-center gap-3 pt-2">
          <button onclick="openLoginModal()" class="w-full sm:w-auto px-6 py-3.5 rounded-2xl btn-amber-orange text-sm font-bold flex items-center justify-center gap-2">
            <i class="fa-solid fa-key text-xs"></i>
            <span>Masukkan Kode Aktivasi / Login Member</span>
          </button>
          <a href="#biaya" class="w-full sm:w-auto px-6 py-3 rounded-2xl bg-white/10 hover:bg-white/15 text-white font-bold text-sm border border-white/20 flex items-center justify-center gap-2 transition-all">
            <i class="fa-solid fa-cart-shopping text-purple-400"></i>
            <span>Daftar / Beli Akses Kelas</span>
          </a>
        </div>
      </div>
    `;
    return;
  }

  // Build Categories & Filter Pills
  const categories = (courseData.curriculumCategories || []).filter(c => c.status !== false).sort((a, b) => a.order - b.order);
  const activeTools = tools.filter(t => t.status !== false);

  const categoryPills = [
    { id: 'all', label: `Semua (${activeTools.length})`, count: activeTools.length }
  ];

  categories.forEach(cat => {
    const inCat = activeTools.filter(t => t.categoryId === cat.id || t.category === cat.name).length;
    if (inCat > 0) {
      categoryPills.push({
        id: cat.id,
        name: cat.name,
        label: `${cat.name} (${inCat})`,
        count: inCat
      });
    }
  });

  if (filtersContainer) {
    filtersContainer.innerHTML = categoryPills.map(cat => {
      const isActive = memberToolFilterCategory === cat.id || (memberToolFilterCategory === cat.name);
      return `
        <button onclick="setMemberToolCategory('${cat.id}')" class="px-3.5 py-1.5 rounded-full text-xs font-semibold whitespace-nowrap transition-all cursor-pointer ${
          isActive 
            ? 'bg-gradient-to-r from-purple-600 to-indigo-600 text-white shadow-md shadow-purple-600/30 font-bold' 
            : 'bg-slate-100 dark:bg-white/10 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-white/20 border border-slate-200 dark:border-white/5'
        }">
          ${cat.label}
        </button>
      `;
    }).join('');
  }

  // Filter based on search query
  let searchFiltered = activeTools;
  if (memberToolSearchQuery && !memberToolSearchQuery.startsWith('@')) {
    const q = memberToolSearchQuery.trim().toLowerCase();
    searchFiltered = activeTools.filter(t => {
      if (t.levelNum !== undefined && t.levelNum !== null) {
        if (t.levelNum.toString() === q) return true;
        if (`level ${t.levelNum}` === q || `lvl ${t.levelNum}` === q || `level-${t.levelNum}` === q) return true;
        const numOnly = q.replace(/[^0-9]/g, '');
        if (numOnly && parseInt(numOnly, 10) === t.levelNum) return true;
      }
      const matchName = (t.name || '').toLowerCase().includes(q);
      const matchDesc = (t.desc || '').toLowerCase().includes(q);
      const matchCat = (t.category || '').toLowerCase().includes(q);
      const matchPrompt = (t.markdownPrompt || '').toLowerCase().includes(q);
      return matchName || matchDesc || matchCat || matchPrompt;
    });
  }

  // CASE 1: SEARCH QUERY ACTIVE
  if (memberToolSearchQuery && memberToolSearchQuery.trim().length > 0) {
    if (searchFiltered.length === 0) {
      container.innerHTML = `
        <div class="col-span-full py-12 text-center text-slate-400">
          <i class="fa-solid fa-folder-open text-3xl mb-3 text-purple-400"></i>
          <p class="text-sm font-semibold">Tidak ada materi yang cocok dengan pencarian "${memberToolSearchQuery}".</p>
          <button onclick="clearMemberToolSearch()" class="mt-3 px-4 py-2 rounded-xl bg-purple-600 text-white text-xs font-bold">
            Reset Pencarian
          </button>
        </div>
      `;
      return;
    }

    container.innerHTML = `
      <div class="col-span-full pb-2">
        <div class="p-3.5 rounded-xl bg-purple-950/40 border border-purple-500/30 flex items-center justify-between text-xs text-purple-300">
          <span>Menampilkan hasil pencarian untuk: <strong>"${memberToolSearchQuery}"</strong></span>
          <span class="font-mono font-bold">${searchFiltered.length} Materi ditemukan</span>
        </div>
      </div>
      ${searchFiltered.map(t => renderSingleMemberToolCard(t)).join('')}
    `;
    return;
  }

  // CASE 2: FILTER SPECIFIC CATEGORY
  if (memberToolFilterCategory !== 'all') {
    const targetCat = categories.find(c => c.id === memberToolFilterCategory || c.name === memberToolFilterCategory);
    const catTools = searchFiltered.filter(t => t.categoryId === memberToolFilterCategory || t.category === memberToolFilterCategory || (targetCat && (t.categoryId === targetCat.id || t.category === targetCat.name)));

    const catName = targetCat ? targetCat.name : memberToolFilterCategory;
    const catDesc = targetCat ? (targetCat.desc || '') : '';
    const catIcon = targetCat ? (targetCat.icon || 'fa-folder-open') : 'fa-folder-open';

    container.innerHTML = `
      <div class="col-span-full pb-2">
        <div class="p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-[#171526] via-[#141520] to-[#0f1017] border border-purple-500/30 shadow-md flex items-center justify-between gap-3">
          <div class="flex items-center gap-3.5">
            <div class="w-10 h-10 rounded-xl bg-purple-600/20 text-purple-400 border border-purple-500/30 flex items-center justify-center text-lg font-bold">
              <i class="fa-solid ${catIcon}"></i>
            </div>
            <div>
              <h3 class="text-base sm:text-lg font-bold text-white tracking-wide">${catName}</h3>
              ${catDesc ? `<p class="text-xs text-slate-400 mt-0.5">${catDesc}</p>` : ''}
            </div>
          </div>
          <span class="px-3 py-1 rounded-full text-xs font-mono font-bold bg-purple-500/20 text-purple-300 border border-purple-500/30 shrink-0">
            ${catTools.length} Materi
          </span>
        </div>
      </div>
      ${catTools.map(t => renderSingleMemberToolCard(t)).join('')}
    `;
    return;
  }

  // CASE 3: ALL CATEGORIES -> Group by Category cleanly!
  let fullHtml = '';
  categories.forEach((cat, idx) => {
    const catTools = searchFiltered.filter(t => t.categoryId === cat.id || t.category === cat.name);
    if (catTools.length === 0) return; // Skip empty category

    fullHtml += `
      <!-- CATEGORY SECTION: ${cat.name} (${catTools.length} Materi) -->
      <div class="col-span-full pt-6 pb-2 ${idx === 0 ? 'pt-0' : 'mt-4 border-t border-white/5'}">
        <div class="p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-[#171526] via-[#141520] to-[#0f1017] border border-purple-500/30 shadow-md flex items-center justify-between gap-3">
          <div class="flex items-center gap-3.5">
            <div class="w-10 h-10 rounded-xl bg-purple-600/20 text-purple-400 border border-purple-500/30 flex items-center justify-center text-lg font-bold">
              <i class="fa-solid ${cat.icon || 'fa-folder-open'}"></i>
            </div>
            <div>
              <h3 class="text-base sm:text-lg font-bold text-white tracking-wide flex items-center gap-2">
                <span>${cat.name}</span>
              </h3>
              ${cat.desc ? `<p class="text-xs text-slate-400 mt-0.5">${cat.desc}</p>` : ''}
            </div>
          </div>
          <span class="px-3 py-1 rounded-full text-xs font-mono font-bold bg-purple-500/20 text-purple-300 border border-purple-500/30 shrink-0">
            ${catTools.length} Materi
          </span>
        </div>
      </div>
      ${catTools.map(t => renderSingleMemberToolCard(t)).join('')}
    `;
  });

  // Check if any uncategorized tools exist
  const categorizedToolIds = new Set();
  categories.forEach(cat => {
    searchFiltered.filter(t => t.categoryId === cat.id || t.category === cat.name).forEach(t => categorizedToolIds.add(t.id));
  });
  const uncatTools = searchFiltered.filter(t => !categorizedToolIds.has(t.id));
  if (uncatTools.length > 0) {
    fullHtml += `
      <div class="col-span-full pt-6 pb-2 mt-4 border-t border-white/5">
        <div class="p-4 sm:p-5 rounded-2xl bg-slate-900 border border-slate-700/50 shadow-md flex items-center justify-between gap-3">
          <div class="flex items-center gap-3">
            <i class="fa-solid fa-folder-open text-slate-400 text-lg"></i>
            <h3 class="text-base font-bold text-white">Materi Lainnya</h3>
          </div>
          <span class="px-3 py-1 rounded-full text-xs font-mono font-bold bg-slate-800 text-slate-300">
            ${uncatTools.length} Materi
          </span>
        </div>
      </div>
      ${uncatTools.map(t => renderSingleMemberToolCard(t)).join('')}
    `;
  }

  container.innerHTML = fullHtml;
}


function getYouTubeEmbedUrl(url) {
  if (!url) return '';
  let videoId = '';
  const match = url.match(/(?:youtu\.be\/|youtube\.com\/(?:embed\/|v\/|watch\?v=|watch\?.+&v=|shorts\/))([\w-]{11})/i);
  if (match && match[1]) {
    videoId = match[1];
    return `https://www.youtube.com/embed/${videoId}?autoplay=1&rel=0`;
  }
  return url;
}

let currentVideoTool = null;
let currentVideoIndex = 0;

function openVideoModal(toolId, videoIndex = 0) {
  const tools = courseData.portalTools || (window.DEFAULT_COURSE_DATA.portalTools || []);
  const tool = tools.find(t => t.id === toolId);
  if (!tool) return;

  currentVideoTool = tool;
  currentVideoIndex = videoIndex;

  const modal = document.getElementById('videoModal');
  const titleEl = document.getElementById('videoModalTitle');
  const catBadge = document.getElementById('videoCategoryBadge');
  const descEl = document.getElementById('videoModalDesc');
  const toolBtn = document.getElementById('videoModalToolBtn');
  const iframe = document.getElementById('videoIframe');
  const playlistContainer = document.getElementById('videoPlaylistContainer');

  // Build video list
  let videos = [];
  if (tool.videos && tool.videos.length > 0) {
    videos = tool.videos;
  } else if (tool.videoUrl) {
    videos = [{ title: 'Video Tutorial Utama', url: tool.videoUrl }];
  }

  const activeVideo = videos[videoIndex] || videos[0] || { title: tool.name, url: tool.videoUrl || '' };

  if (titleEl) {
    titleEl.textContent = videos.length > 1 ? `${tool.name} — ${activeVideo.title}` : tool.name;
  }
  if (catBadge) {
    catBadge.textContent = tool.category || 'Tutorial Video';
  }
  if (descEl) {
    descEl.textContent = tool.desc || 'Tutorial video langkah demi langkah membuat animasi AI.';
  }
  if (toolBtn) {
    if (tool.toolUrl) {
      toolBtn.href = tool.toolUrl;
      toolBtn.style.display = 'inline-flex';
    } else {
      toolBtn.style.display = 'none';
    }
  }

  // Playlist tabs if multiple videos
  if (playlistContainer) {
    if (videos.length > 1) {
      playlistContainer.classList.remove('hidden');
      playlistContainer.innerHTML = `
        <div class="text-[11px] font-bold text-slate-700 dark:text-slate-300 mb-2 flex items-center justify-between">
          <span><i class="fa-solid fa-list-ol text-purple-400 mr-1.5"></i> Daftar Video Materi (${videos.length} Bagian):</span>
          <span class="text-[10px] text-purple-400 font-mono">Sedang memutar: Part ${videoIndex + 1}</span>
        </div>
        <div class="flex flex-wrap gap-2">
          ${videos.map((v, idx) => `
            <button type="button" onclick="switchVideoPart('${tool.id}', ${idx})" class="px-3 py-1.5 rounded-xl text-xs font-semibold transition-all flex items-center gap-1.5 ${
              idx === videoIndex 
                ? 'bg-purple-600 text-white shadow-lg shadow-purple-600/30 font-bold border border-purple-400/40' 
                : 'bg-white/5 hover:bg-white/10 text-slate-300 hover:text-white border border-white/10'
            }">
              <i class="fa-solid ${idx === videoIndex ? 'fa-circle-play text-white' : 'fa-play text-slate-400 text-[10px]'}"></i>
              <span>${v.title || `Part ${idx + 1}`}</span>
            </button>
          `).join('')}
        </div>
      `;
    } else {
      playlistContainer.classList.add('hidden');
      playlistContainer.innerHTML = '';
    }
  }

  if (iframe) {
    iframe.src = getYouTubeEmbedUrl(activeVideo.url);
  }

  if (modal) {
    modal.classList.add('active');
    modal.style.display = 'flex';
  }
  if (document.body) {
    document.body.style.overflow = 'hidden';
  }
}

function switchVideoPart(toolId, index) {
  openVideoModal(toolId, index);
}

function closeVideoModal() {
  const modal = document.getElementById('videoModal');
  const iframe = document.getElementById('videoIframe');
  if (iframe) {
    iframe.src = '';
  }
  if (modal) {
    modal.classList.remove('active');
    modal.style.display = 'none';
  }
  if (document.body) {
    document.body.style.overflow = 'auto';
  }
}

function trackToolView(toolId) {
  const tool = (courseData.portalTools || []).find(t => t.id === toolId);
  if (tool) {
    tool.views = (tool.views || 0) + 1;
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(courseData));
    } catch (e) {}
  }
}

function openToolExternal(toolId) {
  const tool = (courseData.portalTools || []).find(t => t.id === toolId);
  if (!tool || !tool.toolUrl) {
    alert("Link tools belum ditentukan oleh pengelola.");
    return;
  }
  let targetUrl = tool.toolUrl.trim();
  if (!/^https?:\/\//i.test(targetUrl)) {
    targetUrl = 'https://' + targetUrl;
  }
  trackToolView(toolId);
  const win = window.open(targetUrl, '_blank', 'noopener,noreferrer');
  if (!win || win.closed || typeof win.closed === 'undefined') {
    window.location.href = targetUrl;
  }
}


