let currentRegProofBase64 = null;

function switchAuthTab(tab) {
  const paneMasuk = document.getElementById('authPane_masuk');
  const paneDaftar = document.getElementById('authPane_daftar');
  const btnMasuk = document.getElementById('authTabBtn_masuk');
  const btnDaftar = document.getElementById('authTabBtn_daftar');

  if (tab === 'daftar') {
    if (paneMasuk) paneMasuk.classList.add('hidden');
    if (paneDaftar) paneDaftar.classList.remove('hidden');

    if (btnDaftar) {
      btnDaftar.className = 'flex-1 py-2.5 rounded-xl font-bold text-xs sm:text-sm transition-all bg-white text-slate-950 shadow-md';
    }
    if (btnMasuk) {
      btnMasuk.className = 'flex-1 py-2.5 rounded-xl font-semibold text-xs sm:text-sm transition-all text-slate-400 hover:text-white';
    }
  } else {
    if (paneDaftar) paneDaftar.classList.add('hidden');
    if (paneMasuk) paneMasuk.classList.remove('hidden');

    if (btnMasuk) {
      btnMasuk.className = 'flex-1 py-2.5 rounded-xl font-bold text-xs sm:text-sm transition-all bg-white text-slate-950 shadow-md';
    }
    if (btnDaftar) {
      btnDaftar.className = 'flex-1 py-2.5 rounded-xl font-semibold text-xs sm:text-sm transition-all text-slate-400 hover:text-white';
    }
  }
}

function togglePasswordVisibility(inputId, iconId) {
  const input = document.getElementById(inputId);
  const icon = document.getElementById(iconId);
  if (!input) return;

  if (input.type === 'password') {
    input.type = 'text';
    if (icon) icon.className = 'fa-regular fa-eye-slash text-sm text-pink-400';
  } else {
    input.type = 'password';
    if (icon) icon.className = 'fa-regular fa-eye text-sm text-slate-400';
  }
}

