function handleNewAuthLogin() {
  const identifierInput = document.getElementById('memberLoginIdentifier');
  const passwordInput = document.getElementById('memberLoginPassword');

  const rawId = (identifierInput ? identifierInput.value : '').trim();
  const rawPass = (passwordInput ? passwordInput.value : '').trim();

  // Admin Check
  const validAdminUsers = ['admin', 'irtadmin', 'owner', 'irtnaiklevel'];
  const validAdminPass = ['admin123', 'admin', 'irtnaiklevel', '123456'];
  if (validAdminUsers.includes(rawId.toLowerCase()) && validAdminPass.includes(rawPass.toLowerCase())) {
    closeModal('loginModal');
    openPortalAdmin();
    showToast("Berhasil masuk ke Portal Admin!");
    return;
  }

  // Member Login Validation
  if (!rawId && !rawPass) {
    alert("Silakan masukkan Email/Nomor HP dan Password atau Kode Aktivasi Anda.\n\nJika belum punya akun, klik tab 'Daftar' di atas.");
    if (identifierInput) identifierInput.focus();
    return;
  }

  const cleanPass = rawPass.toUpperCase().replace(/[\s\-_]/g, '');
  const digitsOnly = rawPass.replace(/\D/g, '');
  const idLower = rawId.toLowerCase();

  // Deactivated / blocked check
  const isBlocked = (courseData.portalMembers || []).some(m => 
    m.status === 'Nonaktif' && (
      (m.email && m.email.toLowerCase() === idLower) ||
      (m.wa && m.wa.replace(/\D/g, '') === rawId.replace(/\D/g, '')) ||
      (m.activationCode && m.activationCode.toUpperCase() === rawPass.toUpperCase())
    )
  );

  if (isBlocked) {
    alert("⛔ AKSES DITOLAK: Akun ini telah DINONAKTIFKAN oleh Admin.\n\nSilakan hubungi Admin WhatsApp (0813-1989-4236) untuk verifikasi ulang.");
    return;
  }

  // Demo & Universal Codes
  const validCodes = [
    "IRT-ACT-4901", "IRT-ACT-7842", "IRT-MEMBER-2026", "IRT-VIP-2026", "CREATORCLASS2026", "4901", "JOKO"
  ];

  const foundInMembers = (courseData.portalMembers || []).find(m => 
    (m.email && m.email.toLowerCase() === idLower) ||
    (m.wa && rawId && m.wa.replace(/\D/g, '') === rawId.replace(/\D/g, '')) ||
    (m.activationCode && (m.activationCode.toUpperCase() === rawPass.toUpperCase() || m.activationCode.toUpperCase() === rawId.toUpperCase()))
  );

  const foundInPayments = (courseData.portalPayments || []).find(p => 
    (p.email && p.email.toLowerCase() === idLower) ||
    (p.wa && rawId && p.wa.replace(/\D/g, '') === rawId.replace(/\D/g, '')) ||
    (p.activationCode && (p.activationCode.toUpperCase() === rawPass.toUpperCase() || p.activationCode.toUpperCase() === rawId.toUpperCase()))
  );

  const isValidCode = 
    validCodes.includes(rawPass.toUpperCase()) || 
    validCodes.includes(rawId.toUpperCase()) ||
    cleanPass.startsWith('IRTACT') || 
    cleanPass.startsWith('IRT') || 
    digitsOnly === '4901' || 
    rawId.toLowerCase() === 'joko';

  if (foundInMembers || foundInPayments || isValidCode) {
    // Unlock Member - Prioritaskan nama asli dari pembayaran atau member (bukan email prefix)
    let memberName = '';
    if (foundInPayments && foundInPayments.name && !foundInPayments.name.includes('@') && foundInPayments.name.toLowerCase() !== 'calon member') {
      memberName = foundInPayments.name;
    } else if (foundInMembers && (foundInMembers['Nama Lengkap'] || foundInMembers.name) && !(foundInMembers['Nama Lengkap'] || foundInMembers.name).includes('@')) {
      memberName = foundInMembers['Nama Lengkap'] || foundInMembers.name;
    } else if (rawId && !rawId.includes('@') && !/^\d+$/.test(rawId)) {
      memberName = rawId;
    } else {
      memberName = 'Erik';
    }

    const finalActCode = rawPass.toUpperCase() || (foundInPayments && foundInPayments.activationCode) || (foundInMembers && foundInMembers.activationCode) || 'IRT-ACT-7103';

    localStorage.setItem('creator_class_member_unlocked', 'true');
    localStorage.setItem('creator_class_member_name', memberName);
    localStorage.setItem('creator_class_active_code', finalActCode);
    if (rawId.includes('@')) localStorage.setItem('creator_class_member_email', rawId.toLowerCase());
    if (/^\d+$/.test(rawId.replace(/\D/g, ''))) localStorage.setItem('creator_class_member_phone', rawId);

    isMemberUnlocked = true;
    // Set 30-minute session timeout
    localStorage.setItem('creator_class_session_timeout', Date.now() + SESSION_DURATION_MS);
    startMemberSessionTimer();

    // Checkbox Ingatkan Saya (Simpan email & kode)
    const rememberMeCheck = document.getElementById('rememberMeCheck');
    if (rememberMeCheck && rememberMeCheck.checked) {
      localStorage.setItem('remembered_member_email', rawId.toLowerCase());
      localStorage.setItem('remembered_member_code', rawPass || (foundInMembers && foundInMembers.activationCode) || (foundInPayments && foundInPayments.activationCode) || 'IRT-ACT-4901');
    } else {
      localStorage.removeItem('remembered_member_email');
      localStorage.removeItem('remembered_member_code');
    }

    closeModal('loginModal');

    // Show unlocked UI state
    checkMemberUnlockState();
    showToast("Selamat datang kembali, " + memberName + "! Akses materi telah aktif.");

    // Smooth scroll to materi
    const materiSec = document.getElementById('materi');
    if (materiSec) {
      setTimeout(() => materiSec.scrollIntoView({ behavior: 'smooth', block: 'start' }), 300);
    }
  } else {
    const wantRegister = confirm("Akun atau Kode Aktivasi tidak ditemukan.\n\nApakah Anda ingin membuka tab 'Daftar' untuk mendaftar kelas ini sekarang?");
    if (wantRegister) {
      switchAuthTab('daftar');
      const regName = document.getElementById('regFullName');
      if (regName && !rawId.includes('@') && !/^\d+$/.test(rawId)) regName.value = rawId;
      const regEmail = document.getElementById('regEmail');
      if (regEmail && rawId.includes('@')) regEmail.value = rawId;
      const regWa = document.getElementById('regWa');
      if (regWa && /^\d+$/.test(rawId.replace(/\D/g, ''))) regWa.value = rawId;
    } else {
      if (passwordInput) passwordInput.focus();
    }
  }
}

function handleNewAuthRegister() {
  const nameInput = document.getElementById('regFullName');
  const emailInput = document.getElementById('regEmail');
  const waInput = document.getElementById('regWa');

  const name = nameInput ? nameInput.value.trim() : '';
  const email = emailInput ? emailInput.value.trim() : '';
  const wa = waInput ? waInput.value.trim() : '';

  if (!name || !email || !wa) {
    alert("Harap lengkapi Nama Lengkap, Email Aktif, dan Nomor WhatsApp Anda.");
    return;
  }

  // Generate unique Invoice ID and provisional Activation Code
  const randNum = Math.floor(1000 + Math.random() * 9000);
  const invoiceId = 'INV-LYNK-' + randNum;
  const activationCode = 'IRT-ACT-' + randNum;
  const promoPrice = (courseData.pricing && courseData.pricing.promoPrice) ? courseData.pricing.promoPrice : "Rp 99.000";
  const nowFormatted = new Date().toLocaleDateString('id-ID', { 
    day: 'numeric', 
    month: 'short', 
    year: 'numeric', 
    hour: '2-digit', 
    minute: '2-digit' 
  });

  const newPayment = {
    id: invoiceId,
    name: name,
    email: email,
    wa: wa,
    amount: promoPrice,
    method: "Lynk Payment",
    status: "Menunggu Verifikasi",
    activationCode: activationCode,
    proofImage: currentRegProofBase64 || "https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?w=600&auto=format&fit=crop&q=80",
    date: nowFormatted
  };

  if (!courseData.portalPayments) courseData.portalPayments = [];
  courseData.portalPayments.unshift(newPayment);

  if (!courseData.portalMembers) courseData.portalMembers = [];
  courseData.portalMembers.unshift({
    id: 'mem-' + randNum,
    name: name,
    email: email,
    wa: wa,
    status: "Menunggu Aktivasi",
    activationCode: activationCode,
    date: new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }),
    package: "Kelas Animasi AI"
  });

  // Save to LocalStorage
  localStorage.setItem(STORAGE_KEY, JSON.stringify(courseData));

  // Automatically POST to Google Sheets (GAS API)
  if (typeof postDataToGas === 'function') {
    postDataToGas({
      action: 'submitPayment',
      invoiceId: invoiceId,
      activationCode: activationCode,
      name: name,
      email: email,
      wa: wa,
      amount: promoPrice,
      method: "Lynk Payment",
      status: "Menunggu Verifikasi",
      proofImage: currentRegProofBase64 || '-'
    });
  }

  // WhatsApp to Admin
  const adminWa = "6281319894236";
  const msgText = 'Halo Admin CREATOR CLASS! 👋\n\nSaya baru saja mendaftar kelas di website:\n\n📋 *DATA PENDAFTAR:*\n• No. Invoice: *' + invoiceId + '*\n• Nama: *' + name + '*\n• Email: ' + email + '\n• WhatsApp: ' + wa + '\n• Paket: Kelas Animasi AI (' + promoPrice + ')\n\nMohon diverifikasi pembayaran dan diaktifkan akses materi saya. Terima kasih! 🙏';

  const waUrl = 'https://wa.me/' + adminWa + '?text=' + encodeURIComponent(msgText);

  // Switch to Masuk tab and auto-fill
  switchAuthTab('masuk');
  const idInput = document.getElementById('memberLoginIdentifier');
  if (idInput) idInput.value = email;
  const passInput = document.getElementById('memberLoginPassword');
  if (passInput) passInput.value = activationCode;

  showToast("Pendaftaran berhasil dicatat! Mengalihkan ke WhatsApp Admin...");

  setTimeout(() => {
    window.open(waUrl, '_blank');
  }, 600);
}


