// 15. LOGIN MODAL CUSTOMIZATION & 30-MINUTE SESSION ENGINE
// =========================================================================
const SESSION_DURATION_MS = 30 * 60 * 1000; // 30 Menit Auto-Lock

function renderLoginModalCustomization() {
  if (!courseData.loginModalConfig) {
    courseData.loginModalConfig = JSON.parse(JSON.stringify(window.DEFAULT_COURSE_DATA?.loginModalConfig || {}));
  }
  // Auto-upgrade legacy "Studio Prompt" text to "Selamat Datang" matching the new portal design
  if (courseData.loginModalConfig.title === 'Studio Prompt' || !courseData.loginModalConfig.title) {
    courseData.loginModalConfig.title = 'Selamat Datang';
    courseData.loginModalConfig.description = 'Masuk untuk mengakses kelas & aplikasi Anda.';
  }
  const config = courseData.loginModalConfig;
  if (!config) return;

  const logoImg = document.getElementById('loginModalLogoImg');
  if (logoImg) {
    logoImg.src = config.logoUrl || courseData.brand?.logoUrl || "data:image/png;base64,";
  }

  const badgeEl = document.getElementById('loginModalBadge');
  if (badgeEl) {
    badgeEl.textContent = config.badge || 'CREATOR CLASS';
  }

  const titleEl = document.getElementById('loginModalTitle');
  if (titleEl) {
    titleEl.textContent = config.title || 'Selamat Datang';
  }

  const descEl = document.getElementById('loginModalDesc');
  if (descEl) {
    descEl.textContent = config.description || 'Masuk untuk mengakses kelas & aplikasi Anda.';
  }

  const footerEl = document.getElementById('loginModalFooterText');
  if (footerEl) {
    footerEl.innerHTML = (config.footerText || 'Bisa masuk dengan email atau nomor HP terdaftar. Lupa password?') + ' <a href="https://wa.me/6281319894236?text=Halo%20Admin%20CREATOR%20CLASS,%20saya%20lupa%20password/kode%20aktivasi%20saya" target="_blank" class="text-[#ff5882] hover:underline font-semibold">Minta admin mereset.</a>';
  }
}

function handleLoginLogoUpload(event) {
  const file = event.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(e) {
    const dataUrl = e.target.result;
    if (!courseData.loginModalConfig) courseData.loginModalConfig = {};
    courseData.loginModalConfig.logoUrl = dataUrl;

    const urlInput = document.getElementById('settLoginLogoUrl');
    if (urlInput) urlInput.value = dataUrl;

    updateLoginLogoPreview(dataUrl);
    renderLoginModalCustomization();
    autoSaveLandingPageSettings();
    showToast("Foto logo modal login berhasil diunggah!");
  };
  reader.readAsDataURL(file);
}

function handleLoginLogoUrlChange(val) {
  const cleanVal = (val || '').trim();
  if (!courseData.loginModalConfig) courseData.loginModalConfig = {};
  courseData.loginModalConfig.logoUrl = cleanVal;
  updateLoginLogoPreview(cleanVal);
  renderLoginModalCustomization();
  autoSaveLandingPageSettings();
}

function resetLoginLogo() {
  if (!courseData.loginModalConfig) courseData.loginModalConfig = {};
  courseData.loginModalConfig.logoUrl = "data:image/png;base64,";

  const urlInput = document.getElementById('settLoginLogoUrl');
  if (urlInput) urlInput.value = '';

  updateLoginLogoPreview("data:image/png;base64,");
  renderLoginModalCustomization();
  autoSaveLandingPageSettings();
  showToast("Logo modal login direset ke default!");
}

function updateLoginLogoPreview(url) {
  const previewImg = document.getElementById('settLoginLogoPreviewImg');
  const resetBtn = document.getElementById('settLoginLogoResetBtn');

  const finalUrl = url || courseData.brand?.logoUrl || "data:image/png;base64,";
  if (previewImg) {
    previewImg.src = finalUrl;
  }
  if (resetBtn) {
    if (url && url !== "data:image/png;base64,") {
      resetBtn.classList.remove('hidden');
    } else {
      resetBtn.classList.add('hidden');
    }
  }
}

