function handleIdentifierInputAutoFill() {
  const idVal = (document.getElementById('memberLoginIdentifier')?.value || '').trim().toLowerCase();
  const rememberedEmail = (localStorage.getItem('remembered_member_email') || '').toLowerCase();
  const rememberedCode = localStorage.getItem('remembered_member_code') || '';
  const passInput = document.getElementById('memberLoginPassword');

  if (idVal && rememberedEmail && (idVal === rememberedEmail || rememberedEmail.startsWith(idVal))) {
    if (idVal === rememberedEmail && rememberedCode && passInput) {
      passInput.value = rememberedCode;
      // Input type="password" displays naturally as masked dots: ********
    }
  }
}

// -------------------------------------------------------------------------
// 30 MENIT SESSION AUTO-LOCK ENGINE
// -------------------------------------------------------------------------
let memberSessionCheckInterval = null;

function startMemberSessionTimer() {
  if (memberSessionCheckInterval) clearInterval(memberSessionCheckInterval);
  memberSessionCheckInterval = setInterval(checkMemberSessionTimeout, 10000);
}

function checkMemberSessionTimeout() {
  if (!isMemberUnlocked) return;
  const expiry = parseInt(localStorage.getItem('creator_class_session_timeout') || '0', 10);
  if (expiry > 0 && Date.now() > expiry) {
    lockMemberSession();
  }
}

function lockMemberSession() {
  isMemberUnlocked = false;
  localStorage.removeItem('creator_class_member_unlocked');
  localStorage.removeItem('creator_class_session_timeout');

  checkMemberUnlockState();
  openLoginModal('masuk');
  showToast("⏱️ Sesi belajar Anda telah berakhir (30 menit). Silakan masuk kembali.");

  // Pre-fill remembered email and code if available
  const rememberedEmail = localStorage.getItem('remembered_member_email') || '';
  const rememberedCode = localStorage.getItem('remembered_member_code') || '';
  const idInput = document.getElementById('memberLoginIdentifier');
  const passInput = document.getElementById('memberLoginPassword');
  if (idInput && rememberedEmail) idInput.value = rememberedEmail;
  if (passInput && rememberedCode) passInput.value = rememberedCode;
}

