function downloadQrisImage() {
  const qrisImg = document.getElementById('checkoutQrisImg') || document.getElementById('qrisModalImage');
  const base64Data = (courseData && courseData.qrisConfig && courseData.qrisConfig.imageBase64)
    ? courseData.qrisConfig.imageBase64
    : (qrisImg ? qrisImg.src : (window.DEFAULT_COURSE_DATA?.qrisConfig?.imageBase64 || ''));

  if (base64Data && base64Data.startsWith('data:')) {
    try {
      const parts = base64Data.split(';base64,');
      const contentType = parts[0].split(':')[1];
      const raw = window.atob(parts[1]);
      const rawLength = raw.length;
      const uInt8Array = new Uint8Array(rawLength);
      for (let i = 0; i < rawLength; ++i) {
        uInt8Array[i] = raw.charCodeAt(i);
      }
      const blob = new Blob([uInt8Array], { type: contentType });
      const blobUrl = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = blobUrl;
      a.download = 'QRIS-IRT-NAIK-LEVEL.jpg';
      document.body.appendChild(a);
      a.click();
      setTimeout(() => {
        document.body.removeChild(a);
        URL.revokeObjectURL(blobUrl);
      }, 500);
      if (typeof showToast === 'function') {
        showToast("📥 Gambar QRIS berhasil diunduh ke galeri/perangkat Anda!");
      }
      return;
    } catch (e) {
      console.warn('Blob download fallback:', e);
    }
  }

  // Fallback
  const a = document.createElement('a');
  a.href = base64Data || 'qris_irt_naik_level.jpg';
  a.download = 'QRIS-IRT-NAIK-LEVEL.jpg';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  if (typeof showToast === 'function') {
    showToast("📥 Gambar QRIS berhasil diunduh!");
  }
}

function copyDynamicPromoPrice() {
  const promoVal = (courseData && courseData.pricing) ? (courseData.pricing.promoPrice || courseData.pricing.price || 'Rp 99.000') : 'Rp 99.000';
  const numericOnly = promoVal.replace(/\D/g, '');
  const formattedNominal = parseInt(numericOnly, 10).toLocaleString('id-ID');

  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(numericOnly).then(() => {
      if (typeof showToast === 'function') {
        showToast(`📋 Nominal Rp ${formattedNominal} disalin ke clipboard!`);
      }
    }).catch(() => {
      fallbackCopy(numericOnly, formattedNominal);
    });
  } else {
    fallbackCopy(numericOnly, formattedNominal);
  }
}

function fallbackCopy(text, formatted) {
  const temp = document.createElement('textarea');
  temp.value = text;
  document.body.appendChild(temp);
  temp.select();
  try {
    document.execCommand('copy');
    if (typeof showToast === 'function') {
      showToast(`📋 Nominal Rp ${formatted} disalin!`);
    }
  } catch (e) {
    if (typeof showToast === 'function') {
      showToast(`Nominal: Rp ${formatted}`);
    }
  }
  document.body.removeChild(temp);
}

