  courseData.themeConfig.fontBody = bodyFont;

  const hSel = document.getElementById('settFontHeadingSelect');
  if (hSel) hSel.value = headingFont;
  const bSel = document.getElementById('settFontBodySelect');
  if (bSel) bSel.value = bodyFont;

  const mhSel = document.getElementById('memberHeadingFontSelect');
  if (mhSel) mhSel.value = headingFont;
  const mbSel = document.getElementById('memberBodyFontSelect');
