function getActiveThemeConfig() {
  if (courseData && courseData.themeConfig) {
    return courseData.themeConfig;
  }
  return {
    colorTheme: 'obsidian',
    customBg: '#0c0c0e',
    customAccent: '#8b5cf6',
    fontHeading: 'Fraunces',
    fontBody: 'Plus Jakarta Sans'
  };
}

function applyThemeConfig(config) {
  if (!config) config = getActiveThemeConfig();
  const root = document.documentElement;

  // 1. Apply Fonts
  const headingCss = FONT_MAP[config.fontHeading] || FONT_MAP['Fraunces'];
  const bodyCss = FONT_MAP[config.fontBody] || FONT_MAP['Plus Jakarta Sans'];
  root.style.setProperty('--font-heading', headingCss);
  root.style.setProperty('--font-body', bodyCss);

  // Apply to all heading elements directly as inline style fallback
  document.querySelectorAll('.font-heading, h1, h2, h3').forEach(el => {
    el.style.fontFamily = headingCss;
  });

  // 2. Apply Colors - Never set hardcoded body inline styles that conflict with dark/light mode!
  const presetKey = config.colorTheme || 'obsidian';
  const isCurrentlyDark = root.classList.contains('dark');
  
  // Clear conflicting body inline styles so CSS variables and Tailwind work seamlessly
  document.body.style.backgroundColor = '';
  document.body.style.color = '';

  if (presetKey === 'custom' && config.customBg) {
    if (isCurrentlyDark) {
      root.style.setProperty('--bg-page', config.customBg);
    } else {
      root.style.setProperty('--bg-page', '#ffffff');
    }
    if (config.customAccent) {
      root.style.setProperty('--primary', config.customAccent);
    }
  } else if (THEME_PRESETS[presetKey]) {
    const p = THEME_PRESETS[presetKey];
    if (isCurrentlyDark) {
      root.style.setProperty('--bg-page', p.isDark ? p.bgPage : '#0c0c0e');
      root.style.setProperty('--bg-surface', p.isDark ? p.bgSurface : '#121216');
      root.style.setProperty('--bg-card', p.isDark ? p.bgCard : '#16161b');
      root.style.setProperty('--text-main', '#f8fafc');
      root.style.setProperty('--text-muted', '#cbd5e1');
    } else {
      root.style.setProperty('--bg-page', p.isDark ? '#ffffff' : p.bgPage);
      root.style.setProperty('--bg-surface', p.isDark ? '#fafafc' : p.bgSurface);
      root.style.setProperty('--bg-card', p.isDark ? '#ffffff' : p.bgCard);
      root.style.setProperty('--text-main', '#0f172a');
      root.style.setProperty('--text-muted', '#334155');
    }
    root.style.setProperty('--primary', p.primary);
    root.style.setProperty('--primary-hover', p.primaryHover);
    root.style.setProperty('--primary-glow', p.primaryGlow);
  }

  // 3. Update Admin UI Preview if open
  updateThemePreviewBox(config);
}

function updateThemePreviewBox(config) {
  const pBox = document.getElementById('adminThemePreviewBox');
  if (!pBox) return;

  const headingCss = FONT_MAP[config.fontHeading] || FONT_MAP['Fraunces'];
  const bodyCss = FONT_MAP[config.fontBody] || FONT_MAP['Plus Jakarta Sans'];

  const hEl = document.getElementById('adminPreviewHeading');
  if (hEl) hEl.style.fontFamily = headingCss;

  const bEl = document.getElementById('adminPreviewBody');
  if (bEl) bEl.style.fontFamily = bodyCss;

  const lbl = document.getElementById('previewFontLabel');
  if (lbl) lbl.textContent = `${config.fontHeading} + ${config.fontBody}`;

  const card = document.getElementById('adminThemePreviewCard');
  if (card) {
    const preset = THEME_PRESETS[config.colorTheme];
    if (preset) {
      card.style.backgroundColor = preset.bgCard;
      card.style.borderColor = preset.border;
    } else if (config.customBg) {
      card.style.backgroundColor = config.customBg;
    }
  }
}

