function handleCustomBgChange(val) {
  if (!val) return;
  if (!courseData.themeConfig) courseData.themeConfig = getActiveThemeConfig();
  courseData.themeConfig.colorTheme = 'custom';
  courseData.themeConfig.customBg = val;

  const picker = document.getElementById('settCustomBgColor');
  if (picker && picker.value !== val && val.startsWith('#') && val.length === 7) picker.value = val;

  const txt = document.getElementById('settCustomBgText');
  if (txt && txt.value !== val) txt.value = val;

  applyThemeConfig(courseData.themeConfig);
  renderThemeAdminUI();
  if (typeof autoSaveLandingPageSettings === 'function') autoSaveLandingPageSettings();
}

