function saveThemeSettings() {
  if (!courseData.themeConfig) courseData.themeConfig = getActiveThemeConfig();
  const now = new Date();
  const timeStr = now.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) + ' WIB';

  if (typeof autoSaveLandingPageSettings === 'function') {
    autoSaveLandingPageSettings();
  } else {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(courseData));
  }

  const btn = document.getElementById('btnSaveThemeSettings') || document.querySelector('button[onclick="saveThemeSettings()"]');
  if (btn) {
    const origClass = "px-4 py-2 rounded-xl bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-700 hover:to-pink-700 text-white font-bold text-xs shadow-lg shadow-purple-600/30 transition-all flex items-center gap-2";
    const origHtml = `<i class="fa-solid fa-floppy-disk"></i> Simpan Tema & Tipografi`;
    btn.className = "px-4 py-2.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-extrabold text-xs shadow-lg shadow-emerald-500/40 transition-all flex items-center gap-2";
    btn.innerHTML = `<i class="fa-solid fa-circle-check"></i> ✓ Tema Disimpan! (${timeStr})`;
    setTimeout(() => {
      btn.className = origClass;
      btn.innerHTML = origHtml;
    }, 3000);
  }

  if (typeof showToast === 'function') {
    showToast(`🎨 Tema warna & tipografi website berhasil disimpan! (${timeStr})`);
  }
}

