// 16. WEBHOOK LYNK.ID & EMAIL HELPER FUNCTIONS
// =========================================================================
async function resendActivationEmail(email, code, encodedName) {
  if (!email || email === '-' || !email.includes('@')) {
    alert("Email tidak valid atau belum diisi untuk transaksi ini.");
    return;
  }
  const memberName = decodeURIComponent(encodedName || 'Member');
  if (!confirm(`Kirim ulang kode aktivasi (${code}) ke email: ${email}?`)) return;

  showToast(`Mengirim email kode aktivasi ke ${email}...`);
  try {
    // Gunakan POST text/plain agar tidak terkena CORS preflight OPTIONS dari Google Apps Script
    const postRes = await fetch(GAS_API_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify({
        action: 'resendActivationEmail',
        email: email,
        code: code,
        name: memberName
      })
    });
    let result = null;
    try {
      result = await postRes.json();
    } catch(e) {}

    // Fallback via GET jika POST terkendala
    if (!result || !result.success) {
      const getUrl = GAS_API_URL + '?action=resendActivationEmail&email=' + encodeURIComponent(email) + '&code=' + encodeURIComponent(code) + '&name=' + encodeURIComponent(memberName) + '&_t=' + Date.now();
      const getRes = await fetch(getUrl, { cache: 'no-store' });
      result = await getRes.json();
    }

    if (result && result.success) {
      alert(`✅ Berhasil! Email kode aktivasi telah dikirimkan ke:\n${email}\n\n⚠️ PENTING: Mohon infokan member untuk memeriksa:\n1. Folder SPAM / JUNK\n2. Tab PROMOSI / UPDATE di Gmail\n(Terkadang email otomatis masuk ke folder tersebut)`);
      showToast(`Email terkirim ke ${email}`);
    } else {
      alert("Gagal mengirim email: " + (result ? result.error : 'Terjadi kendala pada kuota email'));
    }
  } catch (err) {
    showToast("❌ Gagal menghubungi server: " + err.message);
  }
}

function showWebhookRawPayload(idx) {
  const logs = courseData.portalWebhookLogs || [];
  const logItem = logs[idx];
  if (!logItem) return;
  alert("Log Audit Webhook Lynk.id:\n\n" + JSON.stringify(logItem, null, 2));
}

function renderPortalWebhookLogs() {
  const tbody = document.getElementById('portalWebhookLogsTableBody');
  if (!tbody) return;

  const logs = courseData.portalWebhookLogs || [];
  if (logs.length === 0) {
    tbody.innerHTML = '<tr><td colspan="7" class="py-6 text-center text-xs text-slate-500 italic">Belum ada log transaksi webhook Lynk.id. Begitu ada pembayaran masuk dari Lynk, log audit akan otomatis tercatat di sini.</td></tr>';
    return;
  }

  tbody.innerHTML = logs.map((l, idx) => {
    const st = (l['Status'] || '').toLowerCase();
    let badgeClass = 'bg-slate-800 text-slate-300 border-slate-700';
    if (st.includes('sukses')) {
      badgeClass = 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30';
    } else if (st.includes('diabaikan') || st.includes('duplikat')) {
      badgeClass = 'bg-purple-500/15 text-purple-300 border-purple-500/30';
    } else if (st.includes('perlu dicek') || st.includes('ditolak')) {
      badgeClass = 'bg-rose-500/15 text-rose-300 border-rose-500/30';
    }

    const grandTotalStr = typeof l['GrandTotal'] === 'number' ? ('Rp ' + l['GrandTotal'].toLocaleString('id-ID')) : (l['GrandTotal'] || '-');

    return '<tr class="hover:bg-white/[0.02] transition-colors text-xs">' +
      '<td class="py-3 px-3.5 whitespace-nowrap text-slate-400 font-mono text-[11px]">' + (l['Timestamp'] || '-') + '</td>' +
      '<td class="py-3 px-3.5 whitespace-nowrap font-bold text-white font-mono text-[11px]">' + (l['RefId'] || '-') + '</td>' +
      '<td class="py-3 px-3.5 whitespace-nowrap text-slate-300">' + (l['Email Pembeli'] || '-') + '</td>' +
      '<td class="py-3 px-3.5 whitespace-nowrap font-mono font-bold text-emerald-400">' + grandTotalStr + '</td>' +
      '<td class="py-3 px-3.5 whitespace-nowrap"><span class="px-2 py-0.5 rounded-full text-[10px] font-bold border ' + badgeClass + '">' + (l['Status'] || '-') + '</span></td>' +
      '<td class="py-3 px-3.5 text-slate-300 text-[11px] max-w-xs truncate">' + (l['Hasil / Pesan'] || '-') + '</td>' +
      '<td class="py-3 px-3.5 text-center whitespace-nowrap"><button onclick="showWebhookRawPayload(' + idx + ')" class="p-1 px-2.5 rounded-lg bg-white/5 hover:bg-white/10 text-slate-400 hover:text-white text-[10px] font-mono transition-all">JSON</button></td>' +
    '</tr>';
  }).join('');
}

// =========================================================================
// MULTI-DEVICE LOCK (MAX 2 DEVICES) & REMEMBERED ACCOUNTS ENGINE
// =========================================================================
function getOrCreateDeviceId() {
  let devId = localStorage.getItem('creator_class_device_id');
  if (!devId) {
    devId = 'DEV_' + Math.random().toString(36).substring(2, 9) + Date.now().toString(36);
    localStorage.setItem('creator_class_device_id', devId);
  }
  return devId;
}

function getRememberedAccounts() {
  try {
    const raw = localStorage.getItem('creator_class_remembered_accounts');
    return raw ? JSON.parse(raw) : [];
  } catch (e) {
    return [];
  }
}

function saveRememberedAccount(account) {
  if (!account || !account.email) return;
  const accounts = getRememberedAccounts().filter(a => a.email.toLowerCase() !== account.email.toLowerCase());
  accounts.unshift({
    email: account.email.toLowerCase(),
    name: account.name || account.email.split('@')[0],
    code: account.code || '',
    lastLogin: Date.now()
  });
  // Keep up to 5 remembered accounts
  const trimmed = accounts.slice(0, 5);
  localStorage.setItem('creator_class_remembered_accounts', JSON.stringify(trimmed));
  renderRememberedAccounts();
}

function removeRememberedAccount(email) {
  if (!email) return;
  const accounts = getRememberedAccounts().filter(a => a.email.toLowerCase() !== email.toLowerCase());
  localStorage.setItem('creator_class_remembered_accounts', JSON.stringify(accounts));
  renderRememberedAccounts();
}

function clearAllRememberedAccounts() {
  if (confirm("Hapus semua akun yang tersimpan di perangkat ini?")) {
    localStorage.removeItem('creator_class_remembered_accounts');
    renderRememberedAccounts();
  }
}

function renderRememberedAccounts() {
  const container = document.getElementById('rememberedAccountsSection');
  const listEl = document.getElementById('rememberedAccountsList');
  if (!container || !listEl) return;

  const accounts = getRememberedAccounts();
  if (accounts.length === 0) {
    container.style.display = 'none';
    return;
  }

  container.style.display = 'block';
  listEl.innerHTML = accounts.map(acc => `
    <div onclick="quickLoginWithEmail('${acc.email}')" class="flex items-center justify-between px-3 py-2.5 rounded-xl bg-slate-100 hover:bg-slate-200 dark:bg-white/[0.04] dark:hover:bg-white/[0.08] border border-slate-200 dark:border-white/10 cursor-pointer transition-all group">
      <div class="flex items-center gap-2.5 overflow-hidden">
        <div class="w-6 h-6 rounded-full bg-purple-500/20 text-purple-600 dark:text-purple-300 font-bold flex items-center justify-center text-xs shrink-0">
          👤
        </div>
        <span class="text-xs sm:text-sm font-medium text-slate-800 dark:text-slate-200 truncate group-hover:text-purple-600 dark:group-hover:text-purple-400">
          ${acc.email}
        </span>
      </div>
      <button type="button" onclick="event.stopPropagation(); removeRememberedAccount('${acc.email}')" class="text-slate-400 hover:text-rose-500 p-1 text-xs shrink-0 transition-colors" title="Hapus dari perangkat ini">
        ✕
      </button>
    </div>
  `).join('');
}

function switchLoginModalTab(tab) {
  const btnMember = document.getElementById('tabBtnMember');
  const btnAdmin = document.getElementById('tabBtnAdmin');
  const panelMember = document.getElementById('modalMemberPanel');
  const panelAdmin = document.getElementById('modalAdminPanel');

  if (tab === 'member') {
    if (btnMember) {
      btnMember.className = "flex-1 py-2.5 rounded-xl font-bold text-xs sm:text-sm transition-all bg-white text-slate-950 shadow-md";
    }
    if (btnAdmin) {
      btnAdmin.className = "flex-1 py-2.5 rounded-xl font-semibold text-xs sm:text-sm transition-all text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white";
    }
    if (panelMember) panelMember.style.display = 'block';
    if (panelAdmin) panelAdmin.style.display = 'none';
    renderRememberedAccounts();
  } else {
    if (btnAdmin) {
      btnAdmin.className = "flex-1 py-2.5 rounded-xl font-bold text-xs sm:text-sm transition-all bg-white text-slate-950 shadow-md";
    }
    if (btnMember) {
      btnMember.className = "flex-1 py-2.5 rounded-xl font-semibold text-xs sm:text-sm transition-all text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white";
    }
    if (panelMember) panelMember.style.display = 'none';
    if (panelAdmin) panelAdmin.style.display = 'block';
  }
}

function toggleRedeemView(showRedeem) {
  const emailView = document.getElementById('memberEmailLoginView');
  const redeemView = document.getElementById('memberRedeemView');
  if (showRedeem) {
    if (emailView) emailView.style.display = 'none';
    if (redeemView) redeemView.style.display = 'block';
    const emailInput = document.getElementById('memberQuickEmailInput');
    const redeemEmailInput = document.getElementById('redeemEmailInput');
    if (emailInput && redeemEmailInput && !redeemEmailInput.value) {
      redeemEmailInput.value = emailInput.value.trim();
    }
  } else {
    if (emailView) emailView.style.display = 'block';
    if (redeemView) redeemView.style.display = 'none';
    renderRememberedAccounts();
  }
}

// QUICK LOGIN WITH EMAIL (Pernah masuk di perangkat ini / Masuk langsung dengan email)
async function quickLoginWithEmail(emailOverride) {
  const emailInput = document.getElementById('memberQuickEmailInput');
  const email = (emailOverride || (emailInput ? emailInput.value : '')).trim().toLowerCase();

  if (!email || !email.includes('@')) {
    alert("Silakan masukkan alamat email yang valid!");
    if (emailInput) emailInput.focus();
    return;
  }

  const devId = getOrCreateDeviceId();
  const btn = document.getElementById('btnSubmitQuickEmail');
  const originalText = btn ? btn.innerHTML : '';
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Memverifikasi Perangkat...';
  }

  try {
    // 1. Verify via GAS Backend
    const url = GAS_API_URL + '?action=verifyMemberAccess&email=' + encodeURIComponent(email) + '&deviceId=' + encodeURIComponent(devId) + '&_t=' + Date.now();
    const res = await fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' }, cache: 'no-store' });
    const result = await res.json();

    if (result && (result.deviceLimitExceeded || result.reason === 'DEVICE_LIMIT_EXCEEDED')) {
      alert("❌ AKSES DITOLAK: Batas 2 Perangkat Tercapai!\n\nAkun email ini sudah terdaftar dan aktif di 2 perangkat lain.\nSesuai kebijakan keamanan, 1 akun maksimal digunakan pada 2 perangkat.\n\nJika Anda berganti HP/Laptop, silakan hubungi Admin untuk melakukan Reset Perangkat.");
      return;
    }

    if (result && result.needsCode) {
      alert("Perangkat baru terdeteksi. Silakan masukkan Kode Akses yang dikirimkan ke email Anda untuk mendaftarkan perangkat ini (maksimal 2 perangkat).");
      toggleRedeemView(true);
      const rInput = document.getElementById('redeemEmailInput');
      if (rInput) rInput.value = email;
      const cInput = document.getElementById('redeemCodeInput');
      if (cInput) cInput.focus();
      return;
    }

    if (result && result.success && result.valid !== false) {
      // Login Success!
      const resolvedName = (result.member && (result.member['Nama Lengkap'] || result.member.name)) || email.split('@')[0];
      const resolvedCode = (result.member && (result.member['Kode Aktivasi'] || result.member.activationCode)) || 'IRT-ACT-MEMBER';
      const member = { ...(result.member || {}), name: resolvedName, email, activationCode: resolvedCode };
      localStorage.setItem('creator_class_member_name', resolvedName);
      localStorage.setItem('creator_class_member_email', email);
      localStorage.setItem('creator_class_active_member', JSON.stringify(member));
      localStorage.setItem('creator_class_active_code', member.activationCode || 'IRT-VIP');
      localStorage.setItem('creator_class_member_unlocked', 'true');
      localStorage.setItem('creator_class_session_timeout', String(Date.now() + 24 * 60 * 60 * 1000));
      isMemberUnlocked = true;

      saveRememberedAccount({ email, name: member.name, code: member.activationCode });
      closeModal('loginModal');

      // Clear search & filters to show ALL tools immediately
      try {
        if (typeof selectedMemberCategory !== 'undefined') selectedMemberCategory = 'all';
        if (typeof memberToolSearchQuery !== 'undefined') memberToolSearchQuery = '';
        const searchInput = document.getElementById('memberToolSearchInput');
        if (searchInput) searchInput.value = '';
      } catch (e) {}

      if (typeof updateMemberAccessUI === 'function') updateMemberAccessUI();
      if (typeof renderMemberTools === 'function') renderMemberTools();

      // Direct Smooth Scroll to Materi Tools Section
      window.location.hash = '#materi';
      const materiSec = document.getElementById('materi');
      if (materiSec) {
        materiSec.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }

      showToast("Selamat datang kembali, " + (member.name || 'Kreator') + "! Akses seluruh tools & materi aktif.");
      return;
    }

    // Handle Failures
    if (result && result.reason === 'DEVICE_LIMIT_EXCEEDED') {
      alert("❌ AKSES DITOLAK: Batas 2 Perangkat Tercapai!\n\nAkun email ini sudah terdaftar dan aktif di 2 perangkat lain.\nSesuai kebijakan keamanan, 1 akun maksimal digunakan pada 2 perangkat.\n\nJika Anda berganti HP/Laptop, silakan hubungi Admin untuk melakukan Reset Perangkat.");
      return;
    }

    if (result && result.reason === 'MEMBER_NOT_FOUND') {
      const wantRedeem = confirm("Email (" + email + ") belum terdaftar atau belum diaktivasi.\n\nJika Anda baru saja mendaftar melalui Lynk.id dan memiliki Kode Akses dari email, klik OK untuk memasukkan Kode Akses sekarang.");
      if (wantRedeem) {
        toggleRedeemView(true);
        const rInput = document.getElementById('redeemEmailInput');
        if (rInput) rInput.value = email;
        const cInput = document.getElementById('redeemCodeInput');
        if (cInput) cInput.focus();
      }
      return;
    }

    alert("Gagal masuk: " + ((result && result.message) || "Verifikasi tidak berhasil. Silakan coba lagi."));
  } catch (err) {
    console.warn("GAS verify offline or network error, checking local fallback...", err);
    // Local fallback check
    const localMember = (courseData.portalMembers || []).find(m => m.email && m.email.toLowerCase() === email && m.status !== 'Nonaktif');
    if (localMember) {
      localStorage.setItem('creator_class_active_member', JSON.stringify(localMember));
      localStorage.setItem('creator_class_active_code', localMember.activationCode || 'IRT-VIP');
      localStorage.setItem('creator_class_member_unlocked', 'true');
      isMemberUnlocked = true;
      saveRememberedAccount({ email, name: localMember.name, code: localMember.activationCode });
      closeModal('loginModal');
      if (document.body) document.body.classList.add('member-portal-mode');
      if (typeof updateMemberAccessUI === 'function') updateMemberAccessUI();
      window.scrollTo({ top: 0, behavior: 'smooth' });
      if (typeof renderMemberTools === 'function') renderMemberTools();
      window.location.hash = '#materi';
      if (typeof switchPage === 'function') switchPage('materi');
      showToast("Selamat datang kembali, " + (localMember.name || 'Kreator') + "!");
    } else {
      alert("Tidak dapat menghubungkan ke server. Pastikan koneksi internet Anda aktif.");
    }
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = originalText;
    }
  }
}

// REDEEM ACCESS WITH CODE (Untuk member baru aktivasi pertama kali)
async function handleRedeemAccess() {
  const emailInput = document.getElementById('redeemEmailInput');
  const codeInput = document.getElementById('redeemCodeInput');

  const email = (emailInput ? emailInput.value : '').trim().toLowerCase();
  const code = (codeInput ? codeInput.value : '').trim().toUpperCase();

  if (!email || !email.includes('@')) {
    alert("Silakan masukkan Email Pendaftaran yang Anda gunakan saat membayar di Lynk.id!");
    if (emailInput) emailInput.focus();
    return;
  }

  if (!code) {
    alert("Silakan masukkan Kode Akses yang telah dikirimkan ke email Anda (Contoh: IRT-ACT-XXXX)!");
    if (codeInput) codeInput.focus();
    return;
  }

  const devId = getOrCreateDeviceId();
  const btn = document.getElementById('btnSubmitRedeem');
  const originalText = btn ? btn.innerHTML : '';
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Mengaktivasi Akun...';
  }

  try {
    const url = GAS_API_URL + '?action=verifyMemberAccess&email=' + encodeURIComponent(email) + '&code=' + encodeURIComponent(code) + '&deviceId=' + encodeURIComponent(devId) + '&_t=' + Date.now();
    const res = await fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' }, cache: 'no-store' });
    const result = await res.json();

    if (result && result.success) {
      const resolvedName = (result.member && (result.member['Nama Lengkap'] || result.member.name)) || email.split('@')[0];
      const member = { ...(result.member || {}), name: resolvedName, email, activationCode: code };
      localStorage.setItem('creator_class_member_name', resolvedName);
      localStorage.setItem('creator_class_member_email', email);
      localStorage.setItem('creator_class_active_member', JSON.stringify(member));
      localStorage.setItem('creator_class_active_code', code);
      localStorage.setItem('creator_class_member_unlocked', 'true');
      localStorage.setItem('creator_class_session_timeout', String(Date.now() + 24 * 60 * 60 * 1000));
      isMemberUnlocked = true;

      saveRememberedAccount({ email, name: member.name, code });
      closeModal('loginModal');

      // Clear search & filters to show ALL tools immediately
      try {
        if (typeof selectedMemberCategory !== 'undefined') selectedMemberCategory = 'all';
        if (typeof memberToolSearchQuery !== 'undefined') memberToolSearchQuery = '';
        const searchInput = document.getElementById('memberToolSearchInput');
        if (searchInput) searchInput.value = '';
      } catch (e) {}

      if (typeof updateMemberAccessUI === 'function') updateMemberAccessUI();
      if (typeof renderMemberTools === 'function') renderMemberTools();

      // Direct Smooth Scroll to Materi Tools Section
      window.location.hash = '#materi';
      const materiSec = document.getElementById('materi');
      if (materiSec) {
        materiSec.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }

      showToast("Aktivasi Berhasil! Selamat Datang di Kelas Animasi AI!");
      return;
    }

    if (result && result.reason === 'DEVICE_LIMIT_EXCEEDED') {
      alert("❌ AKSES DITOLAK: Batas 2 Perangkat Tercapai!\n\nAkun Anda sudah terdaftar di 2 perangkat lain. Hubungi Admin untuk melakukan Reset Perangkat.");
      return;
    }

    alert("Aktivasi Gagal: " + ((result && result.message) || "Kode Aktivasi atau Email tidak cocok. Periksa kembali email aktivasi Anda."));
  } catch (err) {
    console.error("Redeem error:", err);
    alert("Terjadi kesalahan jaringan saat aktivasi. Silakan periksa koneksi internet Anda.");
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = originalText;
    }
  }
}

// ADMIN LOGIN FROM MODAL
function handleModalAdminLogin() {
  const userInput = document.getElementById('modalAdminUser');
  const passInput = document.getElementById('modalAdminPass');
  const user = (userInput ? userInput.value : '').trim().toLowerCase();
  const pass = (passInput ? passInput.value : '').trim().toLowerCase();

  const currentAdminPass = (courseData.superadminPassword || courseData.superadmin?.password || 'irtnaiklevel2026').trim().toLowerCase();
  const currentAdminUser = (courseData.superadminUsername || courseData.superadmin?.username || 'admin').trim().toLowerCase();
  const validUsers = [currentAdminUser, 'admin', 'superadmin', 'super_admin', 'super admin', 'irtadmin', 'owner', 'irtnaiklevel', 'irtnaiklevek', 'lia', 'sangcreator', ''];
  const validPass = [currentAdminPass, 'irtnaiklevel2026', 'irtnaiklevek2026', 'irtnaiklevel', 'irtnaiklevek', 'admin123', 'admin', '123456'];

  if (pass && validPass.includes(pass) && (validUsers.includes(user) || !user || user.length > 0)) {
    closeModal('loginModal');
    openPortalAdmin();
    showToast("Berhasil masuk ke Portal Admin IRT NAIK LEVEL!");
  } else {
    alert("Username atau Password Admin salah!");
    if (passInput) passInput.focus();
  }
}

// ADMIN: RESET MEMBER DEVICES (GAS + Local)
async function handleAdminResetDevice(memberEmail) {
  if (!memberEmail) return;
  const wantReset = confirm("Reset semua perangkat terdaftar untuk member: " + memberEmail + "?\n\nSetelah di-reset, member dapat login kembali dari perangkat baru (kuota perangkat kembali 0/2).");
  if (!wantReset) return;

  try {
    const url = GAS_API_URL + '?action=resetMemberDevices&email=' + encodeURIComponent(memberEmail) + '&_t=' + Date.now();
    const res = await fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' }, cache: 'no-store' });
    const result = await res.json();

    if (result && result.success) {
      // Reset local device list
      const mem = (courseData.portalMembers || []).find(m => m.email && m.email.toLowerCase() === memberEmail.toLowerCase());
      if (mem) {
        mem.devices = [];
        mem.registeredDevices = '';
        saveData(courseData);
      }
      if (typeof renderPortalMembers === 'function') renderPortalMembers();
      showToast("Perangkat untuk " + memberEmail + " berhasil di-reset (0/2)!");
    } else {
      alert("Gagal mereset perangkat di cloud: " + ((result && result.message) || 'Error tidak diketahui'));
    }
  } catch (err) {
    console.error("Error resetting devices:", err);
    // Local fallback reset
    const mem = (courseData.portalMembers || []).find(m => m.email && m.email.toLowerCase() === memberEmail.toLowerCase());
    if (mem) {
      mem.devices = [];
      saveData(courseData);
      if (typeof renderPortalMembers === 'function') renderPortalMembers();
      showToast("Perangkat untuk " + memberEmail + " berhasil di-reset secara lokal!");
    }
  }
}


// =========================================================================
// TOGGLE NOTION EMBED VIEWER
// =========================================================================
function toggleNotionEmbed() {
  const wrapper = document.getElementById('notionEmbedWrapper');
  const iframe = document.getElementById('notionEmbedIframe');
  const icon = document.getElementById('notionEmbedIcon');
  const text = document.getElementById('notionEmbedText');
  if (!wrapper) return;

  const isHidden = wrapper.classList.contains('hidden');
  if (isHidden) {
    if (iframe && !iframe.src && iframe.dataset.src) {
      iframe.src = iframe.dataset.src;
    }
    wrapper.classList.remove('hidden');
    if (icon) icon.className = 'fa-solid fa-chevron-up text-purple-400 text-xs';
    if (text) text.textContent = 'Tutup Pembaca';
    wrapper.scrollIntoView({ behavior: 'smooth', block: 'start' });
  } else {
    wrapper.classList.add('hidden');
    if (icon) icon.className = 'fa-solid fa-book-open text-purple-400 text-xs';
    if (text) text.textContent = 'Baca Langsung di Sini';
  }
}


// =========================================================================
// GUIDE MODAL (DETAIL MATERI, LANGKAH PRAKTIK & PROMPT RESMI)
// =========================================================================
function openGuideModal(toolId) {
  const tools = courseData.portalTools || (window.DEFAULT_COURSE_DATA && window.DEFAULT_COURSE_DATA.portalTools) || [];
  const t = tools.find(item => item.id === toolId);
  if (!t) return;

  const modal = document.getElementById('guideModal');
  const modalTitle = document.getElementById('guideModalTitle');
  const modalCategory = document.getElementById('guideModalCategory');
  const modalContent = document.getElementById('guideModalContent');
  if (!modal || !modalContent) return;

  if (modalTitle) modalTitle.textContent = t.name;
  if (modalCategory) modalCategory.textContent = t.category || 'Materi Resmi';

  const stepsHtml = (t.instructions && t.instructions.length > 0)
    ? `
      <div class="space-y-3">
        <h4 class="text-xs font-bold text-slate-300 uppercase tracking-wider flex items-center gap-1.5">
          <i class="fa-solid fa-list-ol text-purple-400"></i> Langkah Praktik demi Langkah:
        </h4>
        <ol class="space-y-2 text-xs sm:text-sm text-slate-300">
          ${t.instructions.map((step, idx) => `
            <li class="p-3 rounded-xl bg-black/40 border border-white/5 flex items-start gap-3">
              <span class="w-6 h-6 rounded-lg bg-purple-500/20 text-purple-300 font-mono font-bold text-xs flex items-center justify-center shrink-0 mt-0.5">
                ${idx + 1}
              </span>
              <span class="flex-1 leading-relaxed">${step}</span>
            </li>
          `).join('')}
        </ol>
      </div>
    `
    : '';

  const textsHtml = (t.fullTexts && t.fullTexts.length > 0)
    ? `
      <div class="space-y-2 mt-4 pt-4 border-t border-white/10">
        <h4 class="text-xs font-bold text-slate-300 uppercase tracking-wider flex items-center gap-1.5">
          <i class="fa-solid fa-align-left text-purple-400"></i> Rangkuman Materi & Catatan Penting:
        </h4>
        <div class="p-4 rounded-xl bg-black/30 border border-white/5 text-xs text-slate-300 space-y-2 leading-relaxed">
          ${t.fullTexts.map(txt => `<p>${txt}</p>`).join('')}
        </div>
      </div>
    `
    : '';

  const videoBtnHtml = (t.videos && t.videos.length > 0)
    ? `
      <div class="mt-5 pt-4 border-t border-white/10 flex flex-wrap gap-2">
        <button onclick="closeModal('guideModal'); openVideoModal('${t.id}')" class="px-5 py-2.5 rounded-xl bg-purple-600 hover:bg-purple-700 text-white font-bold text-xs flex items-center gap-2 shadow-lg shadow-purple-600/30">
          <i class="fa-solid fa-play text-xs"></i>
          <span>Tonton Video Tutorial (${t.videos.length} Video)</span>
        </button>
      </div>
    `
    : '';

  modalContent.innerHTML = stepsHtml + textsHtml + videoBtnHtml;
  modal.classList.remove('hidden');
}

function closeGuideModal() {
  const modal = document.getElementById('guideModal');
  if (modal) modal.classList.add('hidden');
}


// =========================================================================
// MARKDOWN PROMPT MODAL CONTROLLER (FOTO 1 & FOTO 2)
// =========================================================================
let currentActivePromptMarkdown = '';
let currentActivePromptTitle = '';
let currentActivePromptLevelId = '';
let currentPromptTab = 'rendered'; // 'rendered' or 'raw'

function renderSimpleMarkdown(md) {
  if (!md) return '<p class="text-slate-400 italic">Tidak ada konten prompt untuk modul ini.</p>';
  
  let html = md
    // Escape HTML
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    // Headings
    .replace(/^### (.*$)/gim, '<h3 class="text-base sm:text-lg font-bold text-purple-300 mt-5 mb-2 flex items-center gap-2"><i class="fa-solid fa-chevron-right text-xs text-purple-400"></i> $1</h3>')
    .replace(/^## (.*$)/gim, '<h2 class="text-lg sm:text-xl font-black text-white mt-6 mb-3 pb-1 border-b border-white/10">$1</h2>')
    .replace(/^# (.*$)/gim, '<h1 class="text-xl sm:text-2xl font-black text-white mt-6 mb-4">$1</h1>')
    // Bold
    .replace(/\*\*(.*?)\*\*/gim, '<strong class="font-bold text-white">$1</strong>')
    // Blockquote
    .replace(/^> (.*$)/gim, '<blockquote class="p-3 my-3 bg-purple-950/20 border-l-4 border-purple-500 rounded-r-xl text-slate-300 text-xs sm:text-sm italic">$1</blockquote>')
    // Numbered list
    .replace(/^(\d+)\. (.*$)/gim, '<div class="flex items-start gap-3 my-2 text-xs sm:text-sm text-slate-300"><span class="w-6 h-6 rounded-lg bg-purple-500/20 text-purple-300 font-mono font-bold text-xs flex items-center justify-center shrink-0 mt-0.5">$1</span><span class="flex-1 leading-relaxed">$2</span></div>')
    // Bullet list
    .replace(/^- (.*$)/gim, '<div class="flex items-start gap-2.5 my-1.5 text-xs sm:text-sm text-slate-300"><span class="text-purple-400 mt-1">•</span><span class="flex-1 leading-relaxed">$1</span></div>')
    // Horizontal Rule
    .replace(/^---$/gim, '<hr class="my-5 border-white/10">')
    // Paragraphs
    .replace(/\n\n/gim, '</p><p class="my-2.5 leading-relaxed text-xs sm:text-sm text-slate-300">');

  return '<div class="space-y-2 text-slate-300">' + html + '</div>';
}

function openPromptMarkdownModal(toolId) {
  const tools = courseData.portalTools || (window.DEFAULT_COURSE_DATA.portalTools || []);
  const tool = tools.find(t => t.id === toolId);
  if (!tool) return;

  currentActivePromptLevelId = tool.id;
  currentActivePromptTitle = tool.name;

  // Build markdown string
  let md = tool.markdownPrompt;
  if (!md || md.trim().length === 0) {
    if (tool.instructions && tool.instructions.length > 0) {
      md = tool.instructions.map((step, i) => `${i + 1}. ${step}`).join('\n\n');
    } else if (tool.fullTexts && tool.fullTexts.length > 0) {
      md = tool.fullTexts.join('\n\n');
    } else {
      md = tool.desc || 'Panduan praktis materi kelas animasi AI IRT Naik Level.';
    }
  }

  currentActivePromptMarkdown = md;

  const modal = document.getElementById('promptMarkdownModal');
  const titleEl = document.getElementById('pmModalTitle');
  const badgeEl = document.getElementById('pmModalBadge');
  const renderedContainer = document.getElementById('pmModalRendered');
  const rawContainer = document.getElementById('pmModalRaw');
  const footerFile = document.getElementById('pmModalFooterFile');

  if (titleEl) titleEl.textContent = tool.name;
  if (badgeEl) badgeEl.textContent = tool.levelNum >= 0 ? 'LEVEL ' + tool.levelNum : 'MODUL';
  if (footerFile) footerFile.textContent = `File: prompt_${tool.id}.md | Terakhir diperbarui: 22/11/2026`;

  // Render markdown
  if (renderedContainer) renderedContainer.innerHTML = renderSimpleMarkdown(md);
  if (rawContainer) rawContainer.value = md;

  switchPromptTab('rendered');

  if (modal) modal.classList.remove('hidden');
}

function closePromptMarkdownModal() {
  const modal = document.getElementById('promptMarkdownModal');
  if (modal) modal.classList.add('hidden');
}

function switchPromptTab(tab) {
  currentPromptTab = tab;
  const btnRendered = document.getElementById('pmTabBtnRendered');
  const btnRaw = document.getElementById('pmTabBtnRaw');
  const renderedContainer = document.getElementById('pmModalRendered');
  const rawContainer = document.getElementById('pmModalRawWrapper');

  if (tab === 'rendered') {
    if (btnRendered) {
      btnRendered.className = 'px-3.5 py-1.5 rounded-lg text-xs font-bold bg-purple-600 text-white shadow-sm transition-all flex items-center gap-1.5';
    }
    if (btnRaw) {
      btnRaw.className = 'px-3.5 py-1.5 rounded-lg text-xs font-medium text-slate-400 hover:text-white transition-all flex items-center gap-1.5';
    }
    if (renderedContainer) renderedContainer.classList.remove('hidden');
    if (rawContainer) rawContainer.classList.add('hidden');
  } else {
    if (btnRaw) {
      btnRaw.className = 'px-3.5 py-1.5 rounded-lg text-xs font-bold bg-purple-600 text-white shadow-sm transition-all flex items-center gap-1.5';
    }
    if (btnRendered) {
      btnRendered.className = 'px-3.5 py-1.5 rounded-lg text-xs font-medium text-slate-400 hover:text-white transition-all flex items-center gap-1.5';
    }
    if (renderedContainer) renderedContainer.classList.add('hidden');
    if (rawContainer) rawContainer.classList.remove('hidden');
  }
}

function copyPromptMarkdown() {
  if (!currentActivePromptMarkdown) return;
  navigator.clipboard.writeText(currentActivePromptMarkdown).then(() => {
    showToast('✅ Naskah Prompt berhasil disalin ke clipboard!');
    const btnText = document.getElementById('pmCopyBtnText');
    const btnIcon = document.getElementById('pmCopyBtnIcon');
    if (btnText) btnText.textContent = 'Tersalin!';
    if (btnIcon) btnIcon.className = 'fa-solid fa-check text-emerald-400';
    setTimeout(() => {
      if (btnText) btnText.textContent = 'Salin Isi Prompt';
      if (btnIcon) btnIcon.className = 'fa-regular fa-copy';
    }, 2500);
  }).catch(() => {
    showToast('Gagal menyalin, silakan gunakan tombol Teks Mentah');
  });
}

function downloadPromptMarkdown() {
  if (!currentActivePromptMarkdown) return;
  const blob = new Blob([currentActivePromptMarkdown], { type: 'text/markdown;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `prompt_${currentActivePromptLevelId || 'materi'}.md`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showToast('📥 Berkas prompt (.md) berhasil diunduh!');
}

